# ====================== §4 USIEngine class (子エンジン管理) ======================
# ============================================================
# [LEASE 2026-07-15] エンジン IO ストリーム所有権 — 中枢再設計 柱②。
# 「relay は呼出スレッドが単独で eng._q を読む」「PREARB は単一 FIFO」等、
# コメント上の紳士協定だった読み手規律をコード化する。構造化読取り
# (_relay_core / fetch_dl_policy / _harvest_one_dl_ponder / _arb_run_searchmoves)
# は取得時に owner タグを掲示し、リース中の別文脈からの send/readline は
# [LEASE-VIOLATION] として diagnosis に自己申告する (raise はしない —
# 対局継続優先。二重読み事故一族 H3/二重bestmove/stale bestmove の検出器)。
# 既存の dl_*_lock はプロセス間排他として温存 — lease は「ストリームの読み手が
# 今誰か」という直交した宣言。
# ============================================================
_LEASE_TLS = threading.local()


def _lease_acquire(eng, owner):
    """リース取得。ネスト/再入は前ホルダを退避して許容 (トークンで復元)。
    別 owner が保持中の取得は violation ログ (奪取はする — 対局継続優先)。"""
    prev = getattr(eng, "_lease_owner", None)
    if prev is not None and prev != owner:
        _flog(f"[LEASE-VIOLATION] {getattr(eng, 'name', '?')}: "
              f"'{owner}' が取得 — 保持中 '{prev}' と競合 (二重読み手の疑い)")
    eng._lease_owner = owner
    prev_tag = getattr(_LEASE_TLS, "tag", None)
    _LEASE_TLS.tag = owner
    return (prev, prev_tag)


def _lease_release(eng, token):
    prev, prev_tag = token
    eng._lease_owner = prev
    _LEASE_TLS.tag = prev_tag


def _leased(owner):
    """[LEASE] エンジン第1引数の関数をリース境界で包むデコレータ。
    関数本体は無改変 — 取得/解放と violation 観測だけを付与する。"""
    def _wrap(fn):
        @functools.wraps(fn)
        def _inner(eng, *args, **kwargs):
            _tok = _lease_acquire(eng, owner)
            try:
                return fn(eng, *args, **kwargs)
            finally:
                _lease_release(eng, _tok)
        return _inner
    return _wrap


# ── [HEALTH-FSM 2026-07-15] per-engine プロセス生存 FSM ─────────────────────
class HealthState(enum.Enum):
    """per-engine プロセス生存の明示 FSM (LIFECYCLE recon §4.1 の実装)。

    従来 `_alive` bool の writer が 21 サイトに分散し、死の「観測」(reader EOF /
    BrokenPipe / sentinel) と「執行」(quit / relay-kill / shutdown) が同じ属性を
    別基準で書いていた。書き込みを _health_transition 1 関数に集約し、非正準
    遷移を [HEALTH-FSM-VIOLATION] で可視化する (WP5 _ps_transition と同型)。

    recon §4.1.1 の 12 状態案から、他の単一情報源で導出可能なものを畳んだ
    物理 5 状態: ALIVE_IDLE/SEARCHING = _go_sent/_bm_arrived、REVIVE_* =
    _ReviveSlot、DIRTY = ps.nnue1_dirty、DEAD_PENDING/FINAL = damper/レジストリ。
    `_alive` は本 FSM の導出ビットとして維持 (reader ~95 箇所は無傷)。
    """
    UNINIT      = enum.auto()   # __init__ 直後 (proc なし)
    RESTARTING  = enum.auto()   # start() 進行中 (旧 proc 破棄〜readyok 前)
    ALIVE       = enum.auto()   # プロセス生存 (_alive=True と同値)
    TERMINATING = enum.auto()   # quit()/強制 kill 執行中 (send 封鎖)
    DEAD        = enum.auto()   # 死亡 (観測 or 執行完了; _alive=False と同値)


_HEALTH_CANONICAL = frozenset({
    (HealthState.UNINIT,      HealthState.RESTARTING),
    (HealthState.UNINIT,      HealthState.TERMINATING),  # 未起動 quit (掃除 no-op)
    (HealthState.RESTARTING,  HealthState.ALIVE),
    (HealthState.RESTARTING,  HealthState.DEAD),         # 起動失敗
    (HealthState.RESTARTING,  HealthState.TERMINATING),  # start 中の quit/shutdown
    (HealthState.ALIVE,       HealthState.DEAD),         # 死亡観測 (EOF/pipe/sentinel)
    (HealthState.ALIVE,       HealthState.TERMINATING),  # 執行 (quit)
    (HealthState.ALIVE,       HealthState.RESTARTING),   # 生きたまま start() (旧 proc kill 込み)
    (HealthState.TERMINATING, HealthState.DEAD),
    (HealthState.TERMINATING, HealthState.RESTARTING),   # quit→start (lifecycle restart)
    (HealthState.DEAD,        HealthState.RESTARTING),
    (HealthState.DEAD,        HealthState.TERMINATING),  # 死後の quit (shutdown 掃除)
    (HealthState.DEAD,        HealthState.ALIVE),        # [REVIVED-READER] reader 単独死からの復活 (proc 生存)
})


def _health_of(eng) -> "HealthState":
    """per-engine 生存状態の読み口。未装着 (旧オブジェクト/スタブ) は UNINIT。"""
    return getattr(eng, "_health", HealthState.UNINIT)


def _health_transition(eng, new_state, reason, caller=""):
    """[HEALTH-FSM] per-engine 生存状態の唯一の書き込み入口。

    - `_alive` を導出ビットとして同時に維持 (ALIVE のみ True) — 旧 21 writer の代替。
    - 非正準遷移は [HEALTH-FSM-VIOLATION] ログ (raise しない — 対局継続優先)。
    - I2 交差不変条件 (recon §4.3.1): nnue_1 が PONDERING/PONDERHIT 中に DEAD へ
      落ちたらログ — 層1(プロセス)×層2(WP5 探索 FSM) の交差矛盾の観測点。
      relay-kill 系は reason ("sp-idle-kill"/"livelock-kill"/"unresponsive-kill")
      が執行semanticsを運ぶ (TERMINATING を挟まない意図的簡約)。
    """
    old = _health_of(eng)
    if old is new_state:
        eng._alive = (new_state is HealthState.ALIVE)   # 冪等でもビットは同期
        return
    eng._health = new_state
    eng._alive = (new_state is HealthState.ALIVE)
    if (old, new_state) not in _HEALTH_CANONICAL:
        _flog(f"[HEALTH-FSM-VIOLATION] {getattr(eng, 'name', '?')}: "
              f"non-canonical {old.name}->{new_state.name} ({reason} @{caller})")
    else:
        _dlog(f"[HEALTH-FSM] {getattr(eng, 'name', '?')}: "
              f"{old.name}->{new_state.name} ({reason})")
    if new_state is HealthState.DEAD and getattr(eng, "name", "") == "nnue_1":
        _ctx = _REVIVE_CTX_REF
        try:
            if _ctx is not None and _ctx.ps.phase in _PS_PHASE_ACTIVE:
                _flog(f"[HEALTH-FSM-VIOLATION] I2: nnue_1 DEAD while "
                      f"phase={_ctx.ps.phase.name} ({reason})")
        except AttributeError:
            pass


class USIEngine:
    def __init__(self, path, name):
        self.path   = path
        self.name   = name
        self.proc   = None
        self._q     = queue.Queue(maxsize=50000)  # [PATCH-QMAX 2026-07-07] go ponder 中の未消費滞留で満杯→子 stdout 停止を防ぐ
        # [PATCH-Q-DROP 2026-07-07b] queue 満杯時に捨てたスコア無し info 行の累計
        # (エンジン単位・全世代通算。_reader が加算、1000 行ごとに 1 回だけ _flog)。
        self._q_drop_count = 0
        self._alive = False
        self._health = HealthState.UNINIT   # [HEALTH-FSM] writer は _health_transition のみ
        self._send_lock = threading.Lock()   # [SEND-LOCK] stdin 書き込みの直列化
        # [SCRIPT] スクリプト経由起動か (.bat/.cmd は cmd /c、.sh は /bin/sh)。
        # kill 時にプロセスツリーごと終了させる必要がある（シェルだけ kill
        # すると実エンジンが orphan 化）。エンジン名に依存しない汎用機構。
        self._via_shell = False
        # [JOB] Windows Job Object ハンドル。_via_shell 起動時に作成し、子孫を
        # 割り当てる。quit() で _job_terminate → _job_close により WSL 本体含む
        # 全子孫を OS レベルで確実に kill する。非 shell / 非 Windows では None。
        self._job = None
        # [WSL] WSL 経由 .bat の場合に Linux 側 pkill 用パスを保持。
        self._bat_path = None
        # [WSL] 起動世代ごとに一意なタグ。pkill -f でこのタグだけを狙い、
        # 同名の他インスタンス (nnue_1 等) や自分の旧世代を巻き込まない。
        self._wsl_tag = None
        self._wsl_gen = 0
        # [BOOK-DIAG] True にすると Log_Engine_Stderr=false でもこのインスタンス
        # だけ stderr を diagnosis.txt へ流す。短命で出力の少ない子 (bookloader)
        # の死因究明用。start() 前に設定すること。
        self._force_stderr = False
        # can have a different MultiPV without conflicting.
        self._last_multipv_sent = None
        self._live_info_cb = None
        self._live_scored_latest = None
        # [DLD] dlshogi 方言対応。usi 応答の "option name X ..." を採取し、
        # 方言を自動判別する。announced_options が空のまま (採取失敗/旧経路)
        # なら方言は unknown のままで、変換は一切行わない (完全な後方互換)。
        self.announced_options: set = set()

        self._dld_logged: set = set()
        # [SP-GEN 2026-07] go/bestmove 世代カウンタ。SP-echo 構造排除用。
        self._go_sent: int = 0
        self._bm_seen: int = 0
        # [FIX-PH-IDLE-INIT 2026-07-10] _bm_arrived の初期化は restart 分岐
        # (start() の if self.proc is not None: ブロック) にしか無く、*初回*
        # start では未定義のままだった。最初の bestmove 到着で reader の
        # `self._bm_arrived += 1` が AttributeError → reader dead →
        # _alive=False → 「必須エンジン dl_1 が起動していません」で LOGIN
        # 中止 (match 実測)。__init__ で必ず定義して初回/再起動の両経路を揃える。
        self._bm_arrived: int = 0
        # [WO-1 2026-07-08] pyfa_ack 世代タグ受信用。
        self._last_ack_gen: int | None = None
        self._bm_gen: int | None = None
        # [WO-2 2026-07-08] pyfa_rec stats レコード受信用。
        self._last_rec: dict | None = None
        # [FIX-DUP-DRAIN-BM 2026-07-09] 連続 flush で同一 bestmove 行を再ドレイン
        # した子 = 内部局面が凍結した wedged 子の徴候 (実測: 'bestmove 3e2d
        # ponder 3c2d' が 22:18:47→22:21:53 の 4 回の「成功」barrier を生存)。
        # ここは検出のみ — 消費は VOID-REPLAY 回復路 (_re_flush) に限定し、
        # 常駐エンジンの正当な同一 bestmove 再ドレインを restart させない。
        self._last_drained_bm: str | None = None
        self._dup_drained_bm: bool = False
        # [C2 2026-07-09] start() 成功回数。_record_dl_death の二重カウント防止。
        self._start_gen: int = 0
        # [SSH-HB 2026-07-10] .bat エンジン用 stdin 常駐ハートビート停止信号。
        # direct SSH 運用では ServerAliveInterval=5 が TCP keepalive を担保するため
        # 本 HB は冗長 (proxy 経由の idle 切断対策が本来の目的)。ただしふかうら王が
        # 空行を無害に無視することは prebuild_trt_cache.sh Phase 5 で実証済みなら安全。
        self._ssh_hb_stop: threading.Event = threading.Event()
        # [VAST-FIX-B] 子プロセスの CUDA_VISIBLE_DEVICES。空文字列 = 未指定 (全 GPU 可視)。
        self._cuda_visible_devices: str = ""

    def _ssh_stdin_heartbeat(self, proc):
        _n = 0
        _flog(f"[{self.name}] SSH-HB thread started (pid={proc.pid})")
        while not self._ssh_hb_stop.wait(3.0):
            if proc is not self.proc:
                _flog(f"[{self.name}] SSH-HB stopped: proc replaced")
                break
            if not self._alive:
                _flog(f"[{self.name}] SSH-HB stopped: not alive")
                break
            try:
                with self._send_lock:
                    if proc.stdin and not proc.stdin.closed:
                        proc.stdin.write("\n")
                        proc.stdin.flush()
                        _n += 1
            except Exception as _e:
                _flog(f"[{self.name}] SSH-HB stopped: write error {_e!r}")
                break
        _flog(f"[{self.name}] SSH-HB thread exited (sent={_n})")

    def start(self):
        _health_transition(self, HealthState.RESTARTING, "start", caller="USIEngine.start")
        # 再起動時: 旧プロセスを kill してキューを確実に drain する。
        # kill 直後に get_nowait() だけでは OS パイプバッファに残った行を
        # 取り逃がすため、_reader が投入する None センチネルを待ってから
        # 残余を flush する (最大 3s)。
        if self.proc is not None:
            # [UNIFY-2] 再起動時の旧 proc 終了も quit Step5 と同一の単一情報源
            #   _terminate_proc_full に委譲 (分岐ロジックの二重実装を解消)。
            _terminate_proc_full(
                self.proc, job=self._job, via_shell=self._via_shell,
                bat_path=self._bat_path, wsl_tag=self._wsl_tag, name=self.name)
            self._job = None
            try:
                self.proc.wait(timeout=5)
            except Exception as _fe:
                _flog(f"[ignored] {__file__}:1529: {_fe}")
            _drain_deadline = time.perf_counter() + 3.0
            while time.perf_counter() < _drain_deadline:
                try:
                    item = self._q.get(timeout=0.1)
                    if item is None:
                        break          # _reader 終了センチネル
                except queue.Empty:
                    # [BUG-FIX 2026-06-22] 旧 `break` は最初の 100ms 空で抜けていて
                    # _reader の None センチネル待ち (最大 3s) を defeat していた。
                    # continue で deadline まで待ち、旧 reader のラスト stale line を
                    # 確実に消費してから新プロセスを spawn (shared self._q なので
                    # leak すると新所有者の最初の readline が腐ったラインを取る)。
                    continue
            while True:
                try:
                    self._q.get_nowait()
                except queue.Empty:
                    break
            # [#26 Q-GENERATION-SPLIT 2026-06-23] 旧 reader が deadline 3s 内に
            # `finally _q.put(None)` を実行しないと、新 reader 起動後の最初の readline
            # (usiok 待ち) が即 None を取って usiok timeout → RuntimeError → start 失敗。
            # WSL bridge (cmd.exe → wsl.exe → linux nnue) 多段 EOF 伝播が deadline 直前に
            # 間に合わない実機シナリオで再現。新世代 _q を作成して旧 reader の遅延 None
            # 投入が新世代に届かないよう **世代分離** する。
            # (古い _q への put(None) は無参照になり GC される — 副作用なし)
            self._q = queue.Queue(maxsize=50000)  # [PATCH-QMAX 2026-07-07] __init__ と同値に統一
            self.proc = None
            # [CACHE-RESET 2026-06-22] python-side caches を初期化。
            # restart で fresh child は USI default (MultiPV=1, SP=engine default false) で
            # 立ち上がるが、wrapper の cache (_last_multipv_sent / _last_sp_sent /
            # announced_options / _dld_logged) が __init__ 後の値のまま残ると、
            # cache-gated setoption 送信が「同値だから skip」と判定 → 新プロセスは間違った
            # MultiPV/SP で動く silent regression。restart 前にリセットする。
            self._last_multipv_sent = None
            self._last_sp_sent = None
            self.announced_options = set()
            self._dld_logged = set()
            # [PATCH-THREADS-DEDUPE 2026-07-07] fresh child は config 初期値の
            # Threads で立ち上がる — dedupe cache を破棄して必ず再送させる。
            self._dyn_threads_last = None
            # [PVMATE §4 CACHE-RESET] restart 後の dedupe 誤動作を防ぐ。
            self._pvmate_last = None
            # [SP-GEN] 世代カウンタリセット (QUEUE-GEN-BIND と整合)
            self._go_sent = 0
            self._bm_seen = 0
            # [FIX-PH-IDLE 2026-07-10] 到着時点計上カウンタ (reader スレッドが
            # q.put の直後に加算)。_bm_seen (消費時点計上) と異なり「子が既に
            # 答えたか」を消費側のドレイン状況と無関係に観測できる。
            # search_outstanding() の単一情報源。go_sent/bm_seen と必ず同時リセット。
            self._bm_arrived = 0
            self._last_ack_gen = None
            self._bm_gen = None
            self._last_rec = None
            # [FIX-DUP-DRAIN-BM 2026-07-09] fresh child に旧プロセスの drain 履歴を
            # 持ち越さない。
            self._last_drained_bm = None
            self._dup_drained_bm = False
            # [SETOPT-DEFER] fresh child は initialize() で全 option を受け取る。旧プロセス宛ての保留は捨てる。
            self._pending_opts = {}

        # Windows: CREATE_NO_WINDOW でコンソールウィンドウの表示を抑制する。
        # 連鎖 kill は Job Object (KILL_ON_JOB_CLOSE) で保証する。
        # text/encoding/errors(UTF-8+replace)は _popen_utf8 が既定化する
        # ([DECODE-SAFE] 子の不正バイトで _reader を落とさない理由は同ヘルパの docstring 参照)。
        _popen_kwargs = dict(
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=(subprocess.PIPE
                    if (_log_engine_stderr or self._force_stderr)
                    else subprocess.DEVNULL),
            bufsize=1,
            cwd=os.path.dirname(os.path.abspath(self.path)),
        )
        # [VAST-FIX-B] CUDA_VISIBLE_DEVICES で GPU を分割。
        if self._cuda_visible_devices:
            _env = os.environ.copy()
            _env["CUDA_VISIBLE_DEVICES"] = self._cuda_visible_devices
            _popen_kwargs["env"] = _env

        # [SCRIPT] 実行対象の決定 — スクリプト起動共通の策 (特定エンジン専用ではない)。
        # どのスロット (DL_x / nnue_x / mate_solver / Book / corr) であっても、
        # パスの拡張子だけで判定して同じ機構を適用する:
        #   Windows .bat/.cmd: そのまま Popen([path]) すると WinError 193
        #     (実行可能形式でなくシェルが解釈するため) → cmd /c 経由で起動し、
        #     Job Object + (WSL なら) タグ pkill で子孫を連鎖 kill する。
        #   POSIX .sh: /bin/sh 経由で起動 (exec ビット/shebang 不要)。
        #     sh → 実エンジンの多段になるため start_new_session で独立
        #     プロセスグループ化し、kill 時は killpg でツリーごと終了する
        #     (proc.kill() は sh しか殺さず実エンジンが孤児化する — Windows の
        #     cmd.exe 多段と同型の問題への同型の解)。
        #   それ以外 (ネイティブ実行ファイル): リスト直起動。
        _ext = os.path.splitext(self.path)[1].lower()
        if sys.platform == "win32" and _ext in (".bat", ".cmd"):
            _argv = ["cmd", "/c", self.path]
            self._via_shell = True
            # [WSL] .bat が WSL 経由なら quit()/start() の kill 時に
            # Linux 側本体を pkill するためパスを控える。
            self._bat_path = self.path
            # [WSL] この起動世代に一意なタグを生成し、ダミー引数として渡す。
            # engine.bat の %* で WSL の engine プロセスのコマンドラインに乗り、
            # pkill -f <tag> でこのプロセスだけをピンポイント kill できる。
            # USI エンジンは未知の引数を無視するため副作用はない。
            self._wsl_gen += 1
            # [WSL-REAP-KEY] reap キーは親が env で渡した PYFAMATE_WSL_REAP_KEY を
            # 最優先で使う (SPSA 経路では必須 — PyInstaller onefile の
            # engine.exe(bootloader)PID ≠ worker(子python)PID のため、親が proc.pid 起点で
            # pkill するのと worker が os.getpid() で組むタグが一致せず WSL nnue が
            # orphan→局跨ぎ汚染→move3 投了の根因だった)。
            # 非 SPSA の直接 USIEngine 利用 (live board / CSA / 対局) では env 未設定なので
            # os.getpid() (= 親プロセスのみで一意・自己 pkill と整合) を使う。
            # 外殻シェルが PYFAMATE_WSL_REAP_KEY を leak していた場合、複数の interactive
            # Pyfamate が同キーを共有し cross-process collision の可能性あり (実害稀)。
            _reap_key = os.environ.get("PYFAMATE_WSL_REAP_KEY") or str(os.getpid())
            self._wsl_tag = f"PYFMTAG_{self.name}_{_reap_key}_{self._wsl_gen}"
            _argv.append(self._wsl_tag)
            # [BAT-VALIDATE] reap が機能するには engine.bat が %* を WSL へ転送している必要。
            # 転送していない .bat (旧版・手書き) では _wsl_tag が Linux 側 cmdline に
            # 乗らず pkill -f は永久にミス → orphan。起動時に検出して stderr へ警告 (一度限り)。
            if not getattr(self, "_bat_warned", False):
                try:
                    _bat_src = open(self.path, "r", encoding="utf-8", errors="replace").read()
                    if "%*" not in _bat_src:
                        # f-string なので % はエスケープ不要 (旧 %% は %-format 用の
                        # 誤エスケープで「%% *」「`%%*`」と誤案内していた)。
                        _msg = (f"[{self.name}] WARNING: engine.bat does not forward %* "
                                f"— WSL pkill will silently miss and Linux nnue will leak. "
                                f"Add `%*` to the wsl line in: {self.path}")
                        _flog(_msg)
                        try:
                            print(_msg, file=sys.stderr, flush=True)
                        except Exception as _e:
                            _flog(f"[ignored] start: {_e!r}")
                except Exception as _e:
                    _flog(f"[ignored] start: {_e!r}")
                self._bat_warned = True
        elif sys.platform != "win32" and _ext == ".sh":
            # [SCRIPT-POSIX] シェルスクリプト起動。kill はプロセスグループ単位。
            # [ABS-ARGV0 2026-07] POSIX exec は cwd 変更後の相対パスを新 cwd 基準で
            # 解決する (bare 名は PATH のみ)。cwd=エンジンdir に変える本実装では
            # 相対パスが二重解決/不発になるため絶対化する (Windows は親 cwd 基準で
            # 解決するため従来から動いていた — 挙動不変)。
            _argv = ["/bin/sh", os.path.abspath(self.path)]
            self._via_shell = True
            self._bat_path = None     # WSL pkill は Windows 専用の下位機構
            self._wsl_tag = None
            _popen_kwargs["start_new_session"] = True
        else:
            if sys.platform != "win32" and not os.access(self.path, os.X_OK):
                try:
                    os.chmod(self.path, 0o755)
                except OSError as _e:
                    _flog(f"[ignored] start: {_e!r}")
            _argv = [os.path.abspath(self.path)]  # [ABS-ARGV0 2026-07] 同上
            self._via_shell = False
            self._bat_path = None
            self._wsl_tag = None
            # [POSIX-PGRP] POSIX では ELF 直起動でも `start_new_session=True` を立てる。
            # こうしておけば quit/異常終了時に killpg(0) で子孫を一掃でき、yaneuraou が
            # spawn する補助スレッド/子プロセスの orphan を防げる (Win の Job Object 相当)。
            # Windows は CREATE_NEW_PROCESS_GROUP を別ロジック (Popen 後の Job 割当) で扱う
            # ためここでは触らない。
            if sys.platform != "win32":
                _popen_kwargs["start_new_session"] = True

        # [JOB] Windows かつ shell 起動 (.bat→cmd→WSL 等の多段) のとき、
        # CREATE_SUSPENDED で起動し、子が孫を産む前に Job Object へ割り当てて
        # から ResumeThread で実行を開始する。これにより cmd.exe が起こす実エンジン
        # (WSL 本体含む) が全てジョブ管理下に入り、quit() の TerminateJobObject /
        # CloseHandle で確実に連鎖 kill される。
        _CREATE_NO_WINDOW  = 0x08000000
        _CREATE_SUSPENDED  = 0x00000004
        self._job = None
        _use_job = (sys.platform == "win32" and self._via_shell)
        if sys.platform == "win32":
            _flags = _CREATE_NO_WINDOW
            if _use_job:
                _flags |= _CREATE_SUSPENDED
            _popen_kwargs["creationflags"] = _flags

        self.proc = _popen_utf8(_argv, **_popen_kwargs)

        if _use_job:
            # ジョブ作成 → 割り当て → resume。いずれか失敗時は taskkill 系
            # フォールバックに委ねるため resume だけは必ず行う (子を固めない)。
            self._job = _job_create()
            _assigned = _job_assign_pid(self._job, self.proc.pid) if self._job else False
            if not _assigned and self._job is not None:
                _flog(f"[{self.name}] job assign failed — closing job, "
                      "will rely on taskkill fallback in quit()")
                _job_close(self._job)
                self._job = None
            # CREATE_SUSPENDED で起動したので必ず resume する。
            _resumed = _resume_process_main_thread(self.proc.pid)
            if not _resumed:
                _flog(f"[{self.name}] ResumeThread failed — "
                      f"killing suspended pid={self.proc.pid}, "
                      f"retrying without CREATE_SUSPENDED")
                try:
                    self.proc.kill()
                    self.proc.wait(timeout=3)
                except Exception as _e:
                    _flog(f"[ignored] start: {_e!r}")
                if self._job:
                    _job_close(self._job)
                    self._job = None
                _popen_kwargs["creationflags"] = _CREATE_NO_WINDOW
                self.proc = _popen_utf8(_argv, **_popen_kwargs)
                self._job = _job_create()
                if self._job:
                    if not _job_assign_pid(self._job, self.proc.pid):
                        _job_close(self._job)
                        self._job = None
                _flog(f"[{self.name}] restarted without SUSPENDED "
                      f"(pid={self.proc.pid} job={'yes' if self._job else 'no'})")
            else:
                _flog(f"[{self.name}] started under Job Object "
                      f"(pid={self.proc.pid} job={'yes' if self._job else 'no'})")

        _health_transition(self, HealthState.ALIVE, "start-ok", caller="USIEngine.start")
        self._start_gen += 1          # [C2] 世代を進める
        # proc をクロージャに束縛して _reader を起動。再起動後も旧 proc を
        # 読み続けることがないよう、スレッドは this proc に固定される。
        _proc = self.proc
        # [QUEUE-GEN-BIND 2026-07] queue を spawn 時点の実体で束縛する。旧実装は
        # _reader 内で self._q を動的参照しており、restart で self._q を新規に
        # 差し替えた後、死にかけの旧 reader が旧世代の行と None センチネルを
        # 「新しい」queue に注入 → 健常な新子を死亡誤判定して再 restart 連鎖
        # (D-state の fukauraou が SIGKILL 後も EOF を遅延させる Linux で顕在化)。
        _spawn(f"reader/{self.name}", self._reader, _proc, self._q)
        if (_log_engine_stderr or self._force_stderr) and _proc.stderr:
            _spawn(f"stderr/{self.name}", self._stderr_reader, _proc)
        # [SSH-HB 2026-07-10] .bat エンジンの stdin 常駐ハートビート起動。
        # direct SSH では冗長 (ServerAliveInterval で十分) だが、安全側で維持。
        if self._via_shell:
            self._ssh_hb_stop = threading.Event()
            _spawn(f"ssh-hb/{self.name}", self._ssh_stdin_heartbeat, _proc)

    def _stderr_reader(self, proc):
        try:
            for line in proc.stderr:
                line = line.rstrip("\n")
                if line:
                    _flog(f"[{self.name}] STDERR: {line}")
        except Exception as _fe:
            # 撤去前: 一行黙殺。stderr 経路だけが死んで proc.stderr は open のまま
            # 残り、子の stderr write が pipe buffer 満杯 (既定 64KB) でブロック。
            # dlshogi info 等を吸う _force_stderr=True の bookloader 短命子で
            # stdout 側 bestmove も巻き添えで止まり、_reader は EOF を観測できず
            # _alive=True のまま無限待ち (3min weakness と同質の沈黙死)。
            # 真の修正: 必ず proc.stderr を close して子に EPIPE を返し書き込みを
            # unblock。stdout 経路は独立に生きるべきなので _q.put(None) はしない
            # (stderr 異常 ≠ stdout 死亡)。EPIPE で落ちる行儀の悪いエンジンでは
            # stdout EOF が立ち _reader が自然に None センチネル経路へ遷移する。
            _flog(f"[{self.name}] stderr reader died: {_fe!r} "
                  f"— closing child stderr to unblock writer (EPIPE)")
            try:
                proc.stderr.close()
            except Exception as _ce:
                _flog(f"[{self.name}] stderr close after reader death failed: {_ce!r}")

    def _reader(self, proc, q):
        # [QUEUE-GEN-BIND 2026-07] q は spawn 時点の queue (世代固定)。restart で
        # self._q が差し替わっても、この reader の出力は自世代の queue にのみ届く。
        try:
            for line in proc.stdout:
                _ln = _parse_usi_line(line.rstrip("\n"))
                # [PATCH-Q-DROP 2026-07-07b] 満杯時の安全弁。put(block) のまま
                # 放置すると子の stdout パイプ充満→子側探索停止に波及するため、
                # 満杯時は「スコア無し info 行」に限り捨てる。bestmove / readyok /
                # score 付き info / その他プロトコル行は絶対に捨てない。None
                # センチネル (finally 節) も無条件 put。maxsize=50000 ([PATCH-QMAX])
                # があるため通常は発火しない理論上の保険。full() は瞬時値だが、
                # 誤判定しても落ちるのはスコア無し info 1 行のみで無害。
                # [A-1 UsiLine] kind == "info" は非スコア info 行のみ。
                if q.full() and _ln.kind == "info":
                    self._q_drop_count = getattr(self, "_q_drop_count", 0) + 1
                    if self._q_drop_count % 1000 == 1:
                        _flog(f"[{self.name}] reader queue full — "
                              f"dropped {self._q_drop_count} scoreless "
                              f"info lines (cumulative)")
                    continue
                q.put(_ln)
                if _CHILD_TRACE is not None:
                    _child_trace(f"{self.name}> {_ln}")
                # [FIX-PH-IDLE 2026-07-10] 到着時点計上。put の *後* に加算する
                # 順序が安全条件 (「計上済みなのに未キュー」の瞬間を作らない —
                # idle 判定は bm_arrived>=go_sent かつ q 空 を要求するため、
                # 逆順だと本物の回答を取りこぼす窓が生じる)。旧世代 proc の
                # reader が restart 後に加算しないよう QUEUE-GEN-BIND と同じ
                # 世代ガードを張る。
                if _ln.kind == "bestmove" and self.proc is proc:
                    self._bm_arrived += 1
                # [WO-6a 2026-07-08] reader は slot 書き込みのみ — 描画は render loop 側。
                if _ln.kind == "scored" and self._live_info_cb is not None:
                    self._live_scored_latest = _ln
        except (KeyboardInterrupt, SystemExit):
            raise
        except Exception:
            _flog(f"[{self.name}] reader dead:\n" + _safe_format_exc().strip())
        finally:
            # この proc が現在の proc と同一のときのみ _alive を落とす。
            # 再起動後の新 proc に誤って _alive=False を立てないための保護。
            if self.proc is proc:
                _health_transition(self, HealthState.DEAD, "reader-eof", caller="USIEngine._reader")
            q.put(None)  # 終了センチネル (自世代 queue のみ)

    def stop_captured_search(self, proc, gen):
        """Write-only interruption; the existing relay remains the output owner."""
        global _STOP_REARM
        with self._send_lock:
            if (self.proc is not proc or not self._alive or proc is None or proc.stdin is None
                    or self._go_sent != gen or self._bm_arrived >= gen):
                return False
            try:
                proc.stdin.write('stop\n'); proc.stdin.flush()
                self._root_hint_epoch = getattr(self, '_root_hint_epoch', 0) + 1
                _STOP_REARM = True
                if _CHILD_TRACE is not None:
                    _child_trace(f'{self.name}< stop')
                return True
            except (BrokenPipeError, OSError):
                return False

    def send(self, cmd):
        _lo = getattr(self, "_lease_owner", None)
        # [ROOT-HINT] cyfhint is a write-only side message from the candidate-eval worker; it does not
        # read the stream, so it is not a lease (reader) conflict. It still takes the line lock below.
        if _lo is not None and getattr(_LEASE_TLS, "tag", None) != _lo and not cmd.startswith("cyfhint "):
            _flog(f"[LEASE-VIOLATION] {self.name}.send({cmd[:40]!r}) — "
                  f"リース保持者 '{_lo}' 以外の文脈から書き込み")
        if not self._alive or not self.proc or not self.proc.stdin:
            _flog(f"[{self.name}] send skipped (not alive): {cmd}")
            return
        # [SETOPT-DEFER] 新しい探索/同期の前に、探索中に保留した setoption を先に届ける。
        if (getattr(self, "_pending_opts", None)
                and cmd.startswith(("position", "go", "usinewgame", "isready"))):
            _ba = getattr(self, "_bm_arrived", None)
            if _ba is None or self._go_sent <= _ba:
                self._flush_pending_opts()
        try:
            # [SEND-LOCK 2026-07-03] stdin には複数スレッドが書く (main / DL_1
            # Phase-2 継続 / prefetch / ponder dispatch)。TextIOWrapper.write は
            # スレッド安全でなく、行の交錯は子側で「裸の go」等のコマンド破壊に
            # 化ける (28414 の既知リスクコメントの実装)。1 行 = 1 クリティカル
            # セクションで直列化する (_SpsaUsiEngine.send と同規律)。
            with self._send_lock:
                self.proc.stdin.write(cmd + "\n")
                self.proc.stdin.flush()
                # Invalidate asynchronous ordering hints when the position/search changes.
                if cmd.split(' ', 1)[0] in ('position', 'stop', 'ponderhit', 'usinewgame', 'isready', 'quit', 'gameover'):
                    self._root_hint_epoch = getattr(self, '_root_hint_epoch', 0) + 1
                # [SP-GEN 2026-07] go 系コマンド送信時にカウンタをインクリメント
                if cmd.startswith("go"):
                    self._go_sent += 1
                if _CHILD_TRACE is not None:
                    _child_trace(f"{self.name}< {cmd}")
        except BrokenPipeError:
            # Child closed its stdin read-end — it has already exited
            _health_transition(self, HealthState.DEAD, "send-brokenpipe", caller="USIEngine.send")
            try:
                self.proc.stdin.close()
            except Exception as _fe:
                _flog(f"[ignored] {__file__}:1604: {_fe}")
            _flog(f"[{self.name}] send BrokenPipe (process exited): {cmd}")
        except Exception as e:
            _health_transition(self, HealthState.DEAD, "send-error", caller="USIEngine.send")
            _flog(f"[{self.name}] send error: {e}")

    def _note_line(self, line):
        """[SP-GEN 2026-07] bestmove 行を検出して _bm_seen をインクリメント。
        [WO-1 2026-07-08] pyfa_ack を採取して _bm_gen に対応付ける。
        全消費者 (wait_for / read_until / readline / flush_until_ready) が
        _q.get 直後に通すことでカウントの単一情報源となる。
        [WO-0.10/G-02 2026-07-08] _send_lock 配下で更新し read-modify-write 競合を防止。"""
        if line is not None:
            if _usi_is(line, "bestmove"):
                with self._send_lock:
                    self._bm_seen += 1
                    self._bm_gen = self._last_ack_gen
                    self._last_ack_gen = None
            elif line.startswith("info string pyfa_ack "):
                try:
                    with self._send_lock:
                        self._last_ack_gen = int(line.split()[-1])
                except (ValueError, IndexError) as _e:
                    _flog(f"[ignored] _note_line: {_e!r}")
            elif line.startswith("info string pyfa_rec "):
                # [WO-2 2026-07-08] stats レコードを採取。bestmove 確定時に消費。
                try:
                    self._last_rec = json.loads(line[len("info string pyfa_rec "):])
                except (json.JSONDecodeError, ValueError) as _e:
                    _flog(f"[ignored] _note_line: {_e!r}")
        return line

    def bm_is_current(self):
        """[SP-GEN 2026-07] 直近の bestmove が最新の go に対応しているか。"""
        return self._bm_seen == self._go_sent

    def search_outstanding(self):
        """[FIX-PH-IDLE 2026-07-10] 未応答の go が存在するか (到着時点基準)。

        False = 送った全 go に bestmove が既に *到着* 済み (消費済みか否かは
        問わない) = エンジンは idle で、こちらから何か送らない限り新しい
        出力は構造的に来ない。ponderhit 送信可否 / relay 早期脱出の判定に
        使う。go_sent==0 (起動直後/restart 直後) は「不明」なので True を
        返して安全側 (従来挙動) に倒す。"""
        if self._go_sent <= 0:
            return True
        return self._go_sent > self._bm_arrived

    def classify_bestmove(self):
        """[WO-1 2026-07-08] 直近 bestmove の帰属を世代タグで判定。
        Returns: 'current' | 'stale' | 'unknown'"""
        if self._bm_gen is None:
            return "unknown"
        if self._bm_gen == self._go_sent:
            return "current"
        return "stale"

    def wait_for(self, keyword, timeout=300.0):
        # [FAILSAFE-PURGE 2026-06-24] death sentinel (line is None) と
        # timeout (remaining<=0) はどちらも None を返すが、戻り値 None 時
        # 呼び出し側は self._alive を見て区別できる規律を契約に追加。
        # _reader は子死亡時 _q.put(None) と _alive=False を両方立てる
        # (_reader finally 節) ため、wait_for で sentinel を受けた瞬間も _alive=False
        # に同期する (readline と同じ規律)。これにより:
        #   - 起動/REVIVE/restart 経路 (arb1_prestart, _restart_nnue_impl,
        #     _engine_lifecycle_restart, _revive_worker, dl_3 warmup, ...) が
        #     None 戻り直後に not eng._alive で「子は dead — 30s 待つ意味なし」
        #     を即判定できる (旧: send() が BrokenPipeError を出すまで死亡が
        #     露見せず、warmup 経路によっては死亡を見落とす)。
        #   - timeout (子は生きているが応答遅延) は None 戻り + _alive=True
        #     のままなので、呼び出し側は extend / restart を選べる。
        deadline = time.perf_counter() + timeout
        while True:
            remaining = deadline - time.perf_counter()
            if remaining <= 0:
                return None
            try:
                line = self._note_line(self._q.get(timeout=min(remaining, 1.0)))
            except queue.Empty:
                continue
            if line is None:
                # death sentinel — _reader が finally 節で投入。
                # _alive は同 _reader が落としているはずだが、レース回避で
                # ここでも明示的に落とす (readline と同規律)。
                _health_transition(self, HealthState.DEAD, "sentinel", caller="USIEngine.wait_for")
                return None
            if _usi_is(line, keyword):   # [USI-TERM] 終端語は先頭 token 一致
                return line

    def read_until(self, keyword, timeout=60.0):
        """Read lines until keyword appears; also returns all lines including keyword line."""
        lines = []
        deadline = time.perf_counter() + timeout
        while True:
            remaining = deadline - time.perf_counter()
            if remaining <= 0:
                break
            try:
                line = self._note_line(self._q.get(timeout=min(remaining, 1.0)))
            except queue.Empty:
                continue
            if line is None:
                # death sentinel — wait_for と同規律。
                _health_transition(self, HealthState.DEAD, "sentinel", caller="USIEngine.read_until")
                break
            lines.append(line)
            if _usi_is(line, keyword):   # [USI-TERM]
                break
        return lines

    def iter_until(self, keyword, timeout=60.0):
        """[PATCH-ITER-UNTIL 2026-07-07] read_until の逐次 yield 版。

        read_until はリスト一括返却のため、呼び出し側ループ内の early-stop
        (movetime 超過 stop) や live 更新 (live_policy_cb
        throttle) が探索完了後まで一切走らなかった (死にコード化)。行を受信
        次第 yield することで探索中に機能する。timeout / death sentinel
        (None → _alive=False) の規律は read_until と同一。keyword を含む行も
        yield してから終了する。
        """
        deadline = time.perf_counter() + timeout
        while True:
            remaining = deadline - time.perf_counter()
            if remaining <= 0:
                return
            try:
                line = self._note_line(self._q.get(timeout=min(remaining, 1.0)))
            except queue.Empty:
                continue
            if line is None:
                # death sentinel — read_until と同規律。
                _health_transition(self, HealthState.DEAD, "sentinel", caller="USIEngine.iter_until")
                return
            yield line
            if _usi_is(line, keyword):   # [USI-TERM]
                return

    def readline(self, timeout=5.0):
        _lo = getattr(self, "_lease_owner", None)
        if _lo is not None and getattr(_LEASE_TLS, "tag", None) != _lo:
            _flog(f"[LEASE-VIOLATION] {self.name}.readline() — "
                  f"リース保持者 '{_lo}' 以外の文脈から読み取り (H3 型二重読み手)")
        try:
            line = self._note_line(self._q.get(timeout=timeout))
            if line is None:
                # _reader が終了センチネルを投入 = エンジンプロセス死亡。
                # None を返して呼び出し元がエンジン死亡を検知できるようにする。
                _health_transition(self, HealthState.DEAD, "sentinel", caller="USIEngine.readline")
                return None
            return line
        except queue.Empty:
            return ""

    def _force_accept_resync(self):
        # [FIX-LOCK-UNIFY 2026-07-10] flush_until_ready の readyok / bestmove-
        # recovered 到達時にカウンタ乖離を強制同期する安全弁。3 カウンタを
        # _send_lock 配下で一括更新し、send (go_sent++) / _note_line (bm_seen++/
        # bm_gen) との read-modify-write 競合を防ぐ (defense-in-depth; 現状は
        # GIL + 単一スレッドで実害なし)。4 サイトの重複を helper へ集約し、
        # 将来サイト追加時の lock 取りこぼしを防止する。
        with self._send_lock:
            self._bm_seen = self._go_sent
            self._bm_arrived = self._go_sent
            self._last_ack_gen = None
            self._bm_gen = None

    def flush_until_ready(self, timeout=30.0, max_stale_lines=500, relay_cb=None):
        """
        isready を送り readyok が返るまで全出力行を破棄する。

        USI プロトコル仕様上、エンジンは readyok を返す前に前段コマンドへの
        全出力 (info / bestmove 等) をフラッシュすることが保証されている。
        よって readyok 受信 = キュー内の stale 出力が完全に排出済みとなる。

        Parameters
        ----------
        timeout : float
            readyok を待つ全体タイムアウト (秒)。
        max_stale_lines : int
            [Fix 1] readyok 到達前に破棄する stale 行数の上限。
            この値を超えた場合はエンジンが異常状態と判断し False を返す。
            通常対局では stale 行は数行程度 (diagnosis.txt 実測 5 行)。
            デフォルト 500 は十分な余裕を持ちつつ、ループ暴走を防ぐ。

        Returns
        -------
        bool
            True: readyok 受信、同期完了。False: タイムアウト・プロセス終了・
            stale 行数上限超過のいずれか。
        """
        if not self._alive or not self.proc or not self.proc.stdin:
            return False
        self.send("isready")
        deadline = time.perf_counter() + timeout
        _drained_count = 0
        # [FLUSH-TAIL 2026-07-03] 失敗時に「最後に何を drain したか」を残す。
        # grid 初回ランの halt 連鎖 (毎回 "2 stale line(s)" で timeout) は内容が
        # 記録されず子の詰まり位置を特定できなかった。成功時は出さない。
        _drained_tail: list = []
        def _tail_dump() -> str:
            if not _drained_tail:
                return ""
            return " tail=" + " | ".join(_l[:120] for _l in _drained_tail[-8:])
        # [FIX-FLUSH-BM 2026-07-09] drain 中に bestmove を検出したら barrier
        # 完了扱いにする。USI 仕様上 bestmove はエンジンが go を完了した証拠
        # であり、readyok が来なくても着手データは回収済み。readyok 未達で
        # False を返すと呼び出し元が halt→restart し bestmove が消失していた
        # (diagnosis.txt 06:10:20: pyfa_ack 8 | bestmove 1f1e が drain tail)。
        _found_bestmove = False
        # [H3-FIX 2026-07-14] この flush 呼び出し中に観測した bestmove 行を
        # 保持する (呼び出し前に必ず None リセット = 「今回観測した」ことを保証)。
        # relay の stop 窓超過 probe がこれを回収して票として採用する。
        self._drained_bm_line = None
        while True:
            if _drained_count >= max_stale_lines:
                if _found_bestmove:
                    _flog(f"[{self.name}] flush_until_ready: stale line limit "
                          f"reached but bestmove was recovered — barrier OK")
                    self._force_accept_resync()   # [FIX-LOCK-UNIFY]
                    return True
                _flog(f"[{self.name}] flush_until_ready: stale line limit "
                      f"({max_stale_lines}) exceeded — treating as error "
                      f"(elapsed={time.perf_counter() - (deadline - timeout):.1f}s)"
                      f"{_tail_dump()}")
                return False
            remaining = deadline - time.perf_counter()
            if remaining <= 0:
                if _found_bestmove:
                    _flog(f"[{self.name}] flush_until_ready: timeout but "
                          f"bestmove was recovered during drain — barrier OK"
                          f"{_tail_dump()}")
                    self._force_accept_resync()   # [FIX-LOCK-UNIFY]
                    return True
                _flog(f"[{self.name}] flush_until_ready: timeout "
                      f"after draining {_drained_count} stale line(s)"
                      f"{_tail_dump()}")
                return False
            try:
                line = self._note_line(self._q.get(timeout=min(remaining, 1.0)))
            except queue.Empty:
                continue
            if line is None:
                if _found_bestmove:
                    _flog(f"[{self.name}] flush_until_ready: process exited "
                          f"but bestmove was recovered — barrier OK")
                    self._force_accept_resync()   # [FIX-LOCK-UNIFY]
                    return True
                _flog(f"[{self.name}] flush_until_ready: process exited "
                      f"after draining {_drained_count} stale line(s)"
                      f"{_tail_dump()}")
                return False
            if _usi_is(line, "readyok"):   # [USI-TERM]
                if _drained_count > 5:
                    _flog(f"[{self.name}] flush_until_ready: drained "
                          f"{_drained_count} stale line(s) before readyok")
                elif _drained_count > 0:
                    _dlog(f"[{self.name}] flush_until_ready: drained "
                          f"{_drained_count} stale line(s) before readyok")
                # [SP-GEN 2026-07] readyok = 全 stale 排出済み (USI 保証) →
                # カウンタ乖離の安全弁として強制同期する。
                self._force_accept_resync()   # [FIX-LOCK-UNIFY] (readyok 系)
                return True
            if relay_cb is not None and ("dl_live_policy " in line or
                                         "info " in line and " score " in line):
                try:
                    relay_cb(line)
                except Exception as _e:
                    _flog(f"[ignored] flush_until_ready: {_e!r}")
            if line.startswith("bestmove") and not _found_bestmove:
                _found_bestmove = True
                self._drained_bm_line = line   # [H3-FIX] 消費でなく保持 (回収可能に)
                # [FIX-DUP-DRAIN-BM 2026-07-09] 直前の flush と同一 bestmove 行の
                # 再ドレイン = wedged 子疑い。ponder ヒント付きの実手のみ対象
                # (resign/win/裸 bestmove は常駐エンジンで正当に反復しうる)。
                # getattr 防御: 本メソッドは _SpsaUsiEngine/_OpponentEngine 等へ
                # 非束縛共有されるため属性契約漏れを AttributeError にしない
                # ([SP-GEN FIX 2026-07-08] の _note_line 事故と同根の予防)。
                if (" ponder " in line
                        and line == getattr(self, "_last_drained_bm", None)):
                    self._dup_drained_bm = True
                self._last_drained_bm = line
                _flog(f"[{self.name}] flush_until_ready: bestmove observed "
                      f"during drain (line {_drained_count}) — stop-flush 経由"
                      f"では ponder/停止応答の正常な読み捨て (取り逃しではない)"
                      f": {line[:80]}")
            # [ILLEGAL-INPUT-DETECT 2026-07-11] やねうら王/dlshogi 系は「position
            # コマンドに含まれる moves 列に非合法手が混じった」ときに
            # `info string Error! : Illegal Input Move : <usi>` を吐き、以降その
            # go を破棄したうえで探索を止める。orchestrator ↔ 子の局面がずれた
            # 明確なシグナルなので、drain 中に検出したら:
            #   (1) 構造化ログで残す (どの手が非合法として拒否されたか)
            #   (2) 次 go の前に position 全再送を強制するフラグを立てる
            # フラグは _force_position_resync (bool)。呼び出し元が参照するのは
            # 望ましいが、参照側未実装でも False で無害。
            if "Illegal Input Move" in line:
                try:
                    _bad = line.split("Illegal Input Move")[-1].split(":")[-1].strip().split()[0]
                except Exception:
                    _bad = "?"
                _flog(f"[{self.name}] ILLEGAL-INPUT detected during drain: "
                      f"child rejected move {_bad!r} — orchestrator/child board "
                      f"desync suspected; forcing full position resync on next go")
                self._force_position_resync = True
            _drained_count += 1
            _drained_tail.append(line)
            if len(_drained_tail) > 8:
                del _drained_tail[0]
            if _drained_count == 20:
                _flog(f"[{self.name}] flush_until_ready: drain count >= 20 (WARN)")

    def flush_with_stop(self, timeout=30.0, max_stale_lines=500):
        """
        stop を送った後 flush_until_ready を呼ぶ。

        go nodes 2^31 等の長時間探索中に isready だけを送ると、エンジンは
        bestmove を返すまで readyok を保留する (USI 仕様)。636MB モデル等で
        探索が数十秒かかる場合、isready 単独の flush_until_ready は短い
        timeout で失敗し、未解決の isready が残ったまま _dl_2_lock を解放して
        しまう。次のスレッドが再度 isready を送ると二重 isready 状態になり、
        さらなる遅延・タイムアウトを招く。

        本メソッドは isready の前に必ず stop を送ることで、エンジンを確実に
        bestmove 出力フェーズに移行させてから readyok を待つ。

        go が送られていない (= 探索中でない) 状態で stop を送っても USI エンジンは
        無視するか即 readyok を返すため、二重 stop・誤動作は発生しない。

        Parameters
        ----------
        timeout : float
            readyok を待つ全体タイムアウト (秒)。flush_until_ready に渡す。
        max_stale_lines : int
            stale 行数の上限。flush_until_ready に渡す。

        Returns
        -------
        bool
            flush_until_ready の戻り値をそのまま返す。
        """
        self.send("stop")
        return self.flush_until_ready(timeout=timeout, max_stale_lines=max_stale_lines)

    # [DLD] ふかうら王 (やねうら王 deep) 正準キー → dlshogi 本家キーの読み替え表。
    # 出典: dlshogi cppshogi/usi.cpp OptionsMap::init (一次ソースで確認)。
    # 名前のみ異なり値の意味が同一のキーだけを載せる。値の単位が異なるキー
    # (DrawValue[cp] vs Draw_Value_*[勝率‰] 等) は載せない — 誤変換するより
    # 破棄してログで知らせる方が安全。
    # [DLD] USI_Hash の安全ドロップ。DNN MCTS (ふかうら王/dlshogi) は置換表を
    # USI_Hash で持たない (メモリ上限は UCT_NodeLimit / DfPn_Hash)。announce
    # していないときに限り送らない。
    _DLD_DROP_NOTE = {
        "USI_Hash": "DNN MCTS は USI_Hash 非対応 — メモリ上限は UCT_NodeLimit / "
                    "DfPn_Hash で指定する (eval_options.txt 経由)",
    }

    # [DLD] GPU 番号付きキー ↔ 番号なしキーの対応。
    # ふかうら王 V9.00 以降は GPU 番号付きオプション (DNN_Model1 等) を
    # 番号なし (DNN_Model 等) に集約した。ただし Max_GPU は健在
    # (FukauraOuEngine.cpp: options.add("Max_GPU", Option(1,1,1024)))。
    # Disabled_GPU も有効 (1-origin: GPU "1" が最初の GPU)。
    #   V9.00 未満 : 番号付き (DNN_Model1 等) を announce
    #   V9.00 以降 : 番号なし (DNN_Model 等) を announce
    # _dl_*_opts は番号付きで構築しているため、番号なしビルド (V9+) には
    # そのままだと届かない。方言ラベルで分類するのではなく、エンジンが usiok で
    # 実際に announce したキー名へ機械的に合わせて送る (自己申告が真実源)。
    _DLD_NUM_BASE = {
        "DNN_Model1":      "DNN_Model",
        "DNN_Batch_Size1": "DNN_Batch_Size",
        "UCT_Threads1":    "UCT_Threads",
    }

    def _dld_log_once(self, key, msg):
        if key not in self._dld_logged:
            self._dld_logged.add(key)
            _flog(f"[DLD][{self.name}] {msg}")

    # [DNN-PATH] ふかうら王/dlshogi の DNN_Model は EvalDir (既定 'eval') 基準で
    # 解決される。最終パス = cwd / EvalDir / DNN_Model。よって DNN_Model に
    # 'eval/model.onnx' を渡すと cwd/eval/eval/model.onnx を探して "file not found"
    # で即死する (diagnosis 2026-06: Error! ... eval/eval/model.onnx file not found)。
    # EvalDir を明示していない現状では、DNN_Model はファイル名のみ ('model.onnx')
    # であるべき。設定値が先頭 'eval/' または 'eval\' で始まる相対値のときだけ、
    # 先頭 1 階層を剥がして二重 eval を解消する。絶対パスや他フォルダ値は無加工。
    _DNN_MODEL_KEYS = {"DNN_Model", "DNN_Model1"}

    def _dld_fix_dnn_model_value(self, key, val):
        if key not in self._DNN_MODEL_KEYS:
            return val
        _v = str(val)
        # 絶対パス (ドライブ指定/先頭スラッシュ) はユーザー意図として尊重。
        if re.match(r"^[A-Za-z]:[\\/]", _v) or _v.startswith(("/", "\\")):
            return val
        _norm = _v.replace("\\", "/")
        if _norm.lower().startswith("eval/"):
            _stripped = _norm[len("eval/"):]
            # 末尾に区切りだけ残るような病的値は触らない。
            if _stripped and not _stripped.startswith("/"):
                self._dld_log_once(
                    "DNN_Model@" + key,
                    f"{key}: '{_v}' → '{_stripped}' に正規化 "
                    f"(EvalDir 基準の二重 eval/ を解消)")
                return _stripped
        return val

    def translate_option(self, key, val):
        """[DLD] setoption のキー名を、このエンジンが実際に announce したキーへ
        合わせて返す。返り値 [(key, val)] / []。

        方言 (ふかうら王/dlshogi) のラベル分類はしない。ふかうら王の V9.00 を境に
        GPU 番号付き/番号なしのキー名が変わるだけなので、usiok で集めた
        announced_options を真実源にして番号の有無だけを吸収する。これにより
        「ふかうら王を dlshogi と誤分類してキーを壊す」事故も、「V9+ に番号付き
        キーを送って無視される」不発も同時に防げる。

        規則:
          1) announce 済みのキーはそのまま送る。
          2) 番号付き⇔番号なしの対応 (_DLD_NUM_BASE) で、相手側だけ announce
             されていればそちらへ変換して送る。
          3) USI_Hash は announce されていなければ送らない (置換表非使用)。
          4) それ以外・両方未 announce なら無加工で送る (未知キーは無視される)。
        """
        ann = self.announced_options
        if key in ("Cyf_Parent_Info", "Cyf_Root_Hint", "Cyf_Root_Hint_Trace", "Cyf_Frontier_Export") and key not in ann:
            return []
        if not ann:
            return [(key, self._dld_fix_dnn_model_value(key, val))]
        # 1) そのまま announce されている。
        if key in ann:
            return [(key, self._dld_fix_dnn_model_value(key, val))]
        # 2) 番号付き/番号なしの相互変換。
        base = self._DLD_NUM_BASE.get(key)
        if base is not None and base in ann:
            self._dld_log_once(
                key, f"{key} → {base} に正規化 (このビルドは番号なしキー / V9.00+)")
            return [(base, self._dld_fix_dnn_model_value(base, val))]
        if base is None:
            for _num, _base in self._DLD_NUM_BASE.items():
                if _base == key and _num in ann:
                    self._dld_log_once(
                        key, f"{key} → {_num} に正規化 "
                             f"(このビルドは番号付きキー / V9.00 未満)")
                    return [(_num, self._dld_fix_dnn_model_value(_num, val))]
        # 3) USI_Hash 安全ドロップ (DNN MCTS のとき)。
        if key in self._DLD_DROP_NOTE and self._dld_is_dnn_engine():
            self._dld_log_once(
                key, f"{key} を破棄 (未 announce) — {self._DLD_DROP_NOTE[key]}")
            return []
        # 4) それ以外は無加工 (DNN_Model 系なら二重 eval/ だけ補正)。
        return [(key, self._dld_fix_dnn_model_value(key, val))]

    def _dld_is_dnn_engine(self):
        """announce 集合から DNN MCTS エンジン (ふかうら王/dlshogi) かを判定。"""
        ann = self.announced_options
        return any(k in ann for k in
                   ("DNN_Model", "DNN_Model1", "UCT_Threads", "UCT_Threads1",
                    "UCT_Hash"))

    def setoption(self, key, val):
        """[DLD] announce 済みキーへ正規化してから setoption 送信。

        [SP-UNIFY 2026-07-14] Stochastic_Ponder の「実際に送った値」キャッシュ
        (_last_sp_sent) はここで一元更新する。旧設計は dispatch ループだけが
        手動更新し、_broadcast_setoption 経由の送信はキャッシュを素通り →
        「同値だから再送 skip」の構造穴 (解剖 §2.2: SP 真実源 2 系統) だった。
        送信箇所 = キャッシュ更新箇所にすることで、どの経路から送っても
        一貫性が構造的に保たれる。

        [SETOPT-DEFER 2026-09-29] 子に未応答の go (ponder を含む) がある間は送らず保留し、
        次の position/go/usinewgame/isready の直前に送る。YaneuraOu/Stockfish 系の子は
        setoption で探索終了を待つため、go ponder 中の setoption は UI thread を塞ぎ、
        後続の ponderhit/stop が読まれない完全停止になる (games-hunt/arm2-1: ponderhit 直前の
        SlowMover で子が 26 秒無応答→kill→勝勢で投了。child-trace.log で確認)。"""
        _ba = getattr(self, "_bm_arrived", None)
        if _ba is not None and self._go_sent > 0 and self._go_sent > _ba:
            if not hasattr(self, "_pending_opts"):
                self._pending_opts = {}
            self._pending_opts[key] = val
            self._setopt_deferred = getattr(self, "_setopt_deferred", 0) + 1
            if self._setopt_deferred <= 3 or self._setopt_deferred % 100 == 0:
                _flog(f"[SETOPT-DEFER] {self.name}: setoption {key}={val} を保留 (探索中; "
                      f"go_sent={self._go_sent} bm_arrived={_ba}) — 次の position/go 直前に送る "
                      f"(累計 {self._setopt_deferred})")
            return
        self._send_setoption_now(key, val)

    def _send_setoption_now(self, key, val):
        for _k, _v in self.translate_option(key, val):
            self.send(f"setoption name {_k} value {_v}")
        if key == "Stochastic_Ponder":
            self._last_sp_sent = str(val)

    def _flush_pending_opts(self):
        """[SETOPT-DEFER] 保留した setoption を送る (探索が終わっているときだけ呼ばれる)。"""
        _p = getattr(self, "_pending_opts", None)
        if not _p:
            return
        self._pending_opts = {}
        for _k, _v in _p.items():
            self._send_setoption_now(_k, _v)

    def initialize(self, options):
        self.send("usi")
        # [DLD] usiok までの "option name X ..." を採取する。送出キーの番号付き/
        # 番号なし正規化と USI_Hash ドロップ判定は、この announce 集合のみを
        # 根拠に行う (方言ラベルには依存しない)。
        _usi_lines = self.read_until("usiok", timeout=60)
        if not any(_usi_is(_l, "usiok") for _l in (_usi_lines or [])):   # [USI-TERM]
            raise RuntimeError(f"{self.name}: usiok timeout")
        for _l in _usi_lines:
            _m = re.match(r"option\s+name\s+(\S+)\s", _l)
            if _m:
                self.announced_options.add(_m.group(1))
        if self.announced_options:
            if self._dld_is_dnn_engine():
                if ("DNN_Model1" in self.announced_options
                        or "UCT_Threads1" in self.announced_options
                        or "DNN_Batch_Size1" in self.announced_options):
                    _flog(f"[DLD][{self.name}] DNN MCTS / 番号付きキー (ふかうら王 "
                          f"V9.00 未満系) を検出 — announce キーへ正規化して送信")
                else:
                    _flog(f"[DLD][{self.name}] DNN MCTS / 番号なしキー (ふかうら王 "
                          f"V9.00 以降系) を検出 — announce キーへ正規化して送信")
        # [VAST-FIX-B] V9.00+ (番号なしキー) で DNN_Model2..N が options に含まれる
        # 場合、番号付き 2..N キーは破棄し Max_GPU=N に集約する。
        _ann = self.announced_options
        _is_numberless = (_ann and self._dld_is_dnn_engine()
                          and "DNN_Model" in _ann and "DNN_Model1" not in _ann)
        _numbered_gpu_max = 0
        if _is_numberless:
            for _ok in options:
                _mb = re.match(r"DNN_Model(\d+)$", _ok)
                if _mb:
                    _numbered_gpu_max = max(_numbered_gpu_max, int(_mb.group(1)))
        _drop_numbered = set()
        # [FIX-GPU-PARTITION 2026-07-11] 集約値の安全弁: options 側に Max_GPU
        # (スロット分割由来) が明示されていれば、番号付きキー由来の台数が
        # それを超えても分割値でクランプする (可視 GPU 超過の CUDA 死を根絶)。
        if _numbered_gpu_max >= 2 and "Max_GPU" in options:
            try:
                _numbered_gpu_max = min(_numbered_gpu_max, int(options["Max_GPU"]))
            except (TypeError, ValueError) as _e:
                _flog(f"[ignored] initialize: {_e!r}")
        if _is_numberless and _numbered_gpu_max >= 2:
            for _gi in range(2, _numbered_gpu_max + 1):
                for _base in ("DNN_Model", "DNN_Batch_Size", "UCT_Threads"):
                    _drop_numbered.add(f"{_base}{_gi}")
            if "Max_GPU" in _ann:
                self.send(f"setoption name Max_GPU value {_numbered_gpu_max}")
                _flog(f"[DLD] {', '.join(sorted(_drop_numbered))} → "
                      f"Max_GPU={_numbered_gpu_max} に集約 (V9.00+ Multi-GPU)")
            else:
                _drop_numbered.clear()
                _flog(f"[DLD][WARN] Multi-GPU 指定を集約できない "
                      f"(Max_GPU 未 announce) — 単一GPUで続行")
        for key, val in options.items():
            if key in _drop_numbered:
                continue
            self.setoption(key, val)
        self.send("isready")

    def quit(self):
        """
        終了シーケンス:
          Step 1: _alive=False
          Step 2: "quit\\n" を送信 (子が graceful 終了を開始)
          Step 3: stdin を close (EOF 補強; quit を見落とした子への保険)
          Step 4: wait(15s) — DL_2 636MB は終了まで最大15s超かかるため
          Step 5: タイムアウト → kill
          Step 6: wait(5s) でゾンビ回収
        """
        _health_transition(self, HealthState.TERMINATING, "quit", caller="USIEngine.quit")
        self._ssh_hb_stop.set()
        if not self.proc:
            return
        # Step 2
        # [SEND-LOCK] 進行中の send() (DL_1 Phase-2 継続/prefetch スレッド等) と
        # 'quit\n' のバイト交錯を防ぐ (_alive=False は「新規 send」しか防げない —
        # _alive チェック通過済みの書き込み途中スレッドとは lock でしか直列化
        # できない)。交錯すると子が quit を認識できず 15s timeout → hard kill。
        try:
            with self._send_lock:
                if self.proc.stdin and not self.proc.stdin.closed:
                    self.proc.stdin.write("quit\n")
                    self.proc.stdin.flush()
        except (BrokenPipeError, ValueError, OSError) as _e:
            _flog(f"[ignored] quit: {_e!r}")
        # Step 3
        try:
            with self._send_lock:
                if self.proc.stdin and not self.proc.stdin.closed:
                    self.proc.stdin.close()
        except OSError as _fe:
            # [C14 2026-07-10] stdin.close() が子プロセス終了後に EINVAL/EBADF を出すのは
            # 良性 (パイプ相手が既に消滅)。生存中の子で失敗したときのみ警告に上げる。
            # 旧: 誤った ':1781' 固定参照で毎 quit ごとにノイズ ([Errno 22]) を出していた。
            if self.proc.poll() is None:
                _flog(f"[{self.name}] quit: stdin.close() failed on live child: {_fe!r}")
        except Exception as _fe:
            _flog(f"[{self.name}] quit: stdin.close() unexpected: {_fe!r}")
        # Step 4
        try:
            self.proc.wait(timeout=15)
            _flog(f"[{self.name}] quit: graceful exit (rc={self.proc.returncode})")
            # [WSL-REAP-ALWAYS] wsl.exe ラッパの rc=0 は Linux 側 nnue の終了を保証しない
            # (Job/taskkill 境界が WSL の Linux PID 空間まで届かない既知制約)。
            # graceful exit でも、bat 経由 WSL 子なら一度だけ best-effort pkill を撃って
            # Linux 残留を防ぐ (冪等・短 timeout・例外黙殺で本処理を止めない)。
            if self._bat_path:
                try:
                    _wsl_kill_by_batpath(self._bat_path, self._wsl_tag)
                except Exception as _we:
                    _flog(f"[{self.name}] post-graceful WSL pkill failed (non-fatal): {_we!r}")
            return
        except subprocess.TimeoutExpired:
            _flog(f"[{self.name}] quit timeout (15s) — killing")
        except Exception as e:
            _flog(f"[{self.name}] quit wait error: {e}")
        # Step 5
        # [UNIFY-2] 終了の分岐 (Job / taskkill / killpg / 直接 kill + WSL pkill) は
        #   単一情報源 _terminate_proc_full に集約。Job ハンドルは消費後に手放す。
        _terminate_proc_full(
            self.proc, job=self._job, via_shell=self._via_shell,
            bat_path=self._bat_path, wsl_tag=self._wsl_tag, name=self.name)
        self._job = None
        # Step 6
        try:
            self.proc.wait(timeout=5)
            _flog(f"[{self.name}] quit: killed and reaped (rc={self.proc.returncode})")
        except subprocess.TimeoutExpired:
            _flog(f"[{self.name}] quit: reap timeout after kill — "
                  f"tracking pid={self.proc.pid} for deferred reap")
            with _unreapable_lock:
                _unreapable_procs.append(self.proc)
        except Exception as e:
            _flog(f"[{self.name}] quit: reap error: {e}")
        _health_transition(self, HealthState.DEAD, "quit-complete", caller="USIEngine.quit")

# ============================================================
# [D] Dynamic DL timeout helper
# ============================================================


def _calc_remaining_moves(move_count, our_ms=0, *, cfg):
    """残り片方手数を推定 (時間管理用)。

    期待ゲーム長 Rem_Moves_Expected_Game_Ply (既定 260) を基準に算出。
    512 ply ルール上限と min(期待長, 512) を取るため、
    期待長を超えた長手数では 512 ベースへ自然遷移する。

    Result is clamped to [DL_Min_Remaining_Moves, 256] and returned as int.
    """
    _min_rem = cfg.dl_min_remaining_moves
    _expected = cfg.rem_moves_expected_game_ply
    _limit = min(_expected, 512)
    base_moves = max(1.0, (_limit - move_count) / 2.0)
    return _clamp(int(math.ceil(base_moves)), _min_rem, 256)


GoClockInfo = namedtuple(
    "GoClockInfo",
    ["eff_s", "dl_timeout_s", "patched_line", "remaining_ms", "floor_ms", "inc_ms",
     "is_total_budget", "byo_ms"],
)
"""
Unified clock parse result returned by _parse_go_clock().

Fields
------
eff_s         : float  — raw effective seconds per move (no ratio/clamp).
                         0.0 for go infinite / go nodes.
dl_timeout_s  : float  — DL-fetch budget in seconds after applying
                         DL_Time_Ratio / Min / Max (or fallback constant).
                         _parse_go_clock_base() では 0.0 固定。
patched_line  : str    — go-line with btime/wtime 0→byoyomi補完済み。
                         Identical to go_line when no patch was needed.
remaining_ms  : int    — our side's main-clock ms (debug / ponderhit relay).
floor_ms      : int    — per-move byoyomi / Fischer-inc / movetime ms,
                         after Move_Overhead deduction (debug).
inc_ms        : int    — raw Fischer increment ms (0 if not Fischer).
                         relay_until_bestmove の remaining_ms=0 天井算出に使用。
is_total_budget : bool — True のとき eff_s は per-move 予算ではなく残り全予算の
                         合計秒数 (_clock_is_sente=None 経路)。下流は dl_timeout_s
                         のみを使い、eff_s を relay cap 等に渡してはならない。
byo_ms        : int    — raw byoyomi ms (Move_Overhead 減算前)。
                         _apply_time_dynamics の guaranteed_ms 算出に使用。
"""


# ============================================================
# TimeBudget — [FIX-6] 時間予算の事前分割
# ============================================================
TimeBudget = namedtuple(
    "TimeBudget",
    ["relay_s", "dl1_recovery_s", "conviction_s", "arb_s",
     "overhead_s", "total_s", "binding_summary"],
)
"""
[FIX-6] _allocate_time_budget() が返す時間予算の事前分割。

Fields
------
relay_s         : float  — NNUE relay の上限 [s]
dl1_recovery_s  : float  — DL_1 結果回収の上限 [s]
conviction_s    : float  — conviction wait の上限 [s]
arb_s           : float  — ARB (blocking) の上限 [s]
overhead_s      : float  — bestmove 送信等の安全余裕 [s]
total_s         : float  — = eff_s (検証用)
binding_summary : str    — 各スロットサイズの1行サマリー (stats.txt 記録用)
"""


# ============================================================
# PonderState — go ponder / ponderhit / go ハンドラ共有クロック状態
# ============================================================
class PsPhase(enum.Enum):
    """[WP5-FSM 2026-07-15] SP/Ponder ライフサイクルの大域状態。

    旧 bool 群 (active / nnue1_ponder_sent / dl{1,2,3}_ponder_sent /
    mate_skip_pending) の暗黙の組み合わせを明示的状態遷移に置換する。
    per-engine の「未回収 bestmove 債務」は直交する集合
    PonderState.pending_bestmove ({"nnue_1","dl_1"}) が持つ —
    大域 phase に押し込むと組み合わせ爆発になるため 2 層に分ける。

    IDLE      : ponder サイクル外 (本 go 中も IDLE — 本 go は FSM の対象外)
    PONDERING : go ponder 受理済み・ponderhit/stop 未受理
    PONDERHIT : ponderhit 処理中 (relay で bestmove を待つ区間)
    DRAINING  : stop 受理済み・bestmove 債務の回収中
    MATE_SKIP : mate-score skip — エンジン未起動のまま stop/ponderhit 待ち
    """
    IDLE      = enum.auto()
    PONDERING = enum.auto()
    PONDERHIT = enum.auto()
    DRAINING  = enum.auto()
    MATE_SKIP = enum.auto()


# 正準遷移表。ここに無い (old,new) は [PS-FSM-VIOLATION] としてログに残す
# (握り潰さないが落とさない — 対局継続が最優先)。
_PS_CANONICAL = frozenset({
    (PsPhase.IDLE,      PsPhase.PONDERING),
    (PsPhase.IDLE,      PsPhase.MATE_SKIP),
    (PsPhase.PONDERING, PsPhase.PONDERHIT),
    (PsPhase.PONDERING, PsPhase.DRAINING),
    (PsPhase.PONDERING, PsPhase.IDLE),      # go ponder 中断系 (endgame skip / 転送不能)
    (PsPhase.PONDERING, PsPhase.MATE_SKIP), # mate-score skip (go ponder ハンドラ内で降格)
    (PsPhase.PONDERHIT, PsPhase.MATE_SKIP), # ponderhit 中の mate-score skip (stop emergency 武装)
    (PsPhase.MATE_SKIP, PsPhase.PONDERING), # ponderhit head での mate-skip 解除
    (PsPhase.PONDERHIT, PsPhase.IDLE),      # bestmove 送出
    (PsPhase.PONDERHIT, PsPhase.DRAINING),  # ponderhit 処理中の stop (稀)
    (PsPhase.DRAINING,  PsPhase.IDLE),
    (PsPhase.MATE_SKIP, PsPhase.IDLE),
})

# active 相当の派生: ponder サイクルが進行中 (旧 ps.active == True)
_PS_PHASE_ACTIVE = frozenset({PsPhase.PONDERING, PsPhase.PONDERHIT})


def _ps_transition(ctx, new_phase, reason):
    """[WP5-FSM] 状態遷移の唯一の入口。非正準遷移と不変条件 I1
    (IDLE で pending 非空) は [PS-FSM-VIOLATION] で可視化する。
    同一 phase への遷移は no-op (ログのみ抑制) — 冪等呼び出しを許す。"""
    ps = ctx.ps
    old = ps.phase
    if old is new_phase:
        return
    ps.phase = new_phase
    if (old, new_phase) not in _PS_CANONICAL:
        _flog(f"[PS-FSM-VIOLATION] non-canonical {old.name}->{new_phase.name} ({reason})")
    else:
        _dlog(f"[PS-FSM] {old.name}->{new_phase.name} ({reason}) "
              f"pending={sorted(ps.pending_bestmove)}")
    if new_phase is PsPhase.IDLE and ps.pending_bestmove:
        # I1: IDLE では債務ゼロのはず。残っていれば回収漏れ (§2③ GUI ハング因子)。
        # reset 系 (usinewgame/gameover) は次局の pre-flush が残骸を排出するため
        # 警告のみで強制クリアはしない (犯人特定のため観測を残す)。
        _flog(f"[PS-FSM-VIOLATION] I1: IDLE with pending={sorted(ps.pending_bestmove)} ({reason})")


def _ps_debt_add(ctx, engine_key, reason=""):
    """[WP5-FSM] go ponder を送った者が立てる bestmove 債務。"""
    ctx.ps.pending_bestmove.add(engine_key)
    _dlog(f"[PS-FSM] debt+ {engine_key} ({reason}) pending={sorted(ctx.ps.pending_bestmove)}")


def _ps_debt_clear(ctx, engine_key, reason=""):
    """[WP5-FSM] bestmove を drain/消費した者が消す債務。無ければ no-op。"""
    if engine_key in ctx.ps.pending_bestmove:
        ctx.ps.pending_bestmove.discard(engine_key)
        _dlog(f"[PS-FSM] debt- {engine_key} ({reason}) pending={sorted(ctx.ps.pending_bestmove)}")


@dataclasses.dataclass
class PonderState:
    """go ponder → ponderhit → go の 3 ハンドラが読み書きするクロック関連状態を一元管理する。

    設計意図
    --------
    旧実装では下記フィールドが main() のローカル変数として分散しており、
    どのタイミングで何が有効かを追うのが困難だった。
    PonderState にまとめることで:
      - 「active=True なのに clock=None」など不整合をクラス境界で検出しやすい
      - usinewgame 時のリセットを reset() 一呼び出しで完結できる
      - 各ハンドラが ps.<field> = ... と書くだけで更新漏れを防げる

    フィールド
    ----------
    go_line          : 直前の timed go コマンド行 (自分手番)。
                       ponderhit recovery / bare "go ponder" 補完に使う。
    ponder_line      : 補完済み "go ponder" 行 (bare の場合は go_line で補完済み)。
    ponder_clock     : _parse_go_clock() が返した GoClockInfo。
                       None = まだ go ponder を受信していない。
    handover_game_phase      : 直近 go / go ponder で算出した handover_game_phase（GP閾値）。
                       _start_prefetch_after_bestmove(ctx, ) などが参照する。
    phase            : PsPhase — ponder ライフサイクルの大域状態 (旧 active の後継)。
    pending_bestmove : set — 未回収 bestmove 債務 (旧 *_ponder_sent 4 兄弟の後継)。
    position         : "go ponder" 直前に送った position 行。
                       ponderhit recovery / prefetch cache key に使う。
    tree_invalid     : ponderhit recovery が完了した後、次の go ponder ハンドラへ
                       「位置を再送してから go ponder せよ」と伝えるフラグ。
    (mate-score skip は phase=MATE_SKIP で表現 — stop ハンドラの emergency
    経路と ponderhit head の解除がこれを消費する。)
    """
    # [WP5-FSM 2026-07-15] 大域状態 + per-engine bestmove 債務 (単一真実源)。
    # 旧 bool 群 (active / nnue1_ponder_sent / dl{1,2,3}_ponder_sent /
    # mate_skip_pending) は撤去 — 読者は phase / pending_bestmove から導出する:
    #   active            ⇔ phase in _PS_PHASE_ACTIVE
    #   nnue1_ponder_sent ⇔ "nnue_1" in pending_bestmove
    #   dlN_ponder_sent   ⇔ "dl_N"  in pending_bestmove
    #   mate_skip_pending ⇔ phase is PsPhase.MATE_SKIP
    phase:             PsPhase             = PsPhase.IDLE
    pending_bestmove:  set                 = dataclasses.field(default_factory=set)
    go_line:           str | None          = None
    go_clock:          GoClockInfo | None  = None
    ponder_line:       str | None          = None
    ponder_clock:      GoClockInfo | None  = None
    # [PNDR-PARITY 2026-07] 相手番パリティで parse した GoClockInfo。prefetch 予算
    # (_calc_dynamic_top_n / _prefetch_budget_arms_core) と MPON 等「相手の思考時間」
    # を必要とする消費者専用。ponder_clock 本体は自分番 (ponderhit 後の自分の手の
    # relay/TA 予算) — 旧実装は move_count-1 のパリティ反転で全消費者が相手時計を
    # 掴んでいた (自他の時計が近い selfplay では無症状の潜伏バグ)。
    ponder_clock_opp:  GoClockInfo | None  = None
    handover_game_phase:       float                 = 1.0        # GP 閾値。初期値は _game_phase_handover_default (≒1.0)
                                                          # game_phase >= handover_game_phase のとき DL 切替
    position:          str | None          = None
    # [USI-SFEN-KIFU 2026-07-09] 直近の「確定局面を伴う go」(通常 go または
    # ponderhit) を処理した時点の position 行。go ponder の予測局面 (position
    # フィールド) と異なり、実際に指された手のみを含むことが保証される。
    # 局後 SFEN 出力 (_usi_game_sfen_flush) が「現局面 = 予測局面のまま終局」
    # を検出して幻の予測手を落とすために参照する。
    last_go_position:  object                = None  # str | None
    # [STALE-BOARDKEY] go ponder 開始時の予測局面 board-key。ponderhit 到着時に
    # 現権威盤キーと照合し、position 文字列比較を board-key 判定に置換する。
    ponder_board_key:  object                = None
    tree_invalid:      bool                  = False
    # [WP5-FSM 2026-07-15] 旧 bool 6 兄弟 (active / mate_skip_pending /
    # nnue1_ponder_sent / dl{1,2,3}_ponder_sent) は撤去 — phase / pending_bestmove
    # が単一真実源。「送った者が debt_add、drain した者が debt_clear」の規律は
    # engine_key ("nnue_1"/"dl_1") で継承。
    # [SP-DIRTY 2026-07] flush 失敗 = パイプ汚染疑い。
    # 次 go ponder 冒頭で再同期し、成功でクリア。
    # usinewgame / _restart_nnue_1 成功時もクリア。
    nnue1_dirty:       bool                  = False
    # [DL-Ponder/Prefetch置換] 全DLが現在 go ponder している局面 (position_cmd)。
    # bestmove 時早期 ponder (予測局面) と GUI go ponder (確定局面) の dedup 判定、
    # および harvest の true-ponderhit 判定に使う。NNUE の教訓
    # (ps.position 一致チェックで stale ツリー再利用を防ぐ) の DL 版。
    dl_ponder_pos:     object                = None  # str | None
    last_eff_s:        object                = None  # float | None
    def reset(self, handover_default: float) -> None:
        """usinewgame 受信時に全フィールドを初期状態へ戻す。"""
        self.phase             = PsPhase.IDLE
        self.pending_bestmove  = set()
        self.go_line           = None
        self.go_clock          = None
        self.ponder_line       = None
        self.ponder_clock      = None
        self.ponder_clock_opp  = None
        self.handover_game_phase       = handover_default
        self.position          = None
        self.last_go_position  = None   # [USI-SFEN-KIFU]
        self.ponder_board_key  = None   # [STALE-BOARDKEY]
        self.tree_invalid      = False
        self.nnue1_dirty       = False  # [SP-DIRTY]
        self.dl_ponder_pos     = None
        # [FIX time-loss #1] 直近 go の eff_s [秒]。_stop_dl_ponders の drain
        # budget を eff_s 連動で締めるために _handle_go が毎手書き込む。
        self.last_eff_s        = None


# ---------------------------------------------------------------------------
# A1 リファクタリング: list-as-cell ホルダを dataclass に束ねる
# ---------------------------------------------------------------------------
# 変更前: _dl_2_invoked_h=[False], _dl_2_result=[None] など 1 要素リストが
#   スレッド/クロージャ間の可変状態として散在していた (39 箇所)。
# 変更後: 関連する可変状態を dataclass に集約し、属性アクセスで読み書きする。
#   これにより「どのスレッドが何を書くか」がクラス定義から一目で分かる。
# ---------------------------------------------------------------------------

@dataclasses.dataclass
class NnueHealthState:
    """EngineContext が保持する nnue_1 の再起動・安定性カウンタ。"""
    restart_fail_streak  : int  = 0
    unstable_mode        : bool = False
    hash_degraded        : bool = False
    hash_original        : int  = 0

    def reset(self) -> None:
        """usinewgame 受信時にカウンタをリセット。"""
        self.restart_fail_streak  = 0
        self.unstable_mode        = False
        # hash_degraded / hash_original は reset() で消さない。
        # usinewgame の HASH-DEGRADE-RESTORE ブロックが復元試行後に自分でクリアする。


@dataclasses.dataclass
class GameProgressState:
    """EngineContext が保持するゲーム進行状態ホルダ群。

    フィールド
    ----------
    last_nnue_score_cp    : 直前手の nnue スコア [cp] (go_clock / ponder 判定に使用)
    last_bestmove_depth   : 直前手の探索深さ [depth] (CSA コメント送信に使用)
    dl_1_model_current    : 現在ロード済み DL_1 モデルパス
    [Step 4D] dl_3_rescue_pending / dl_3_rescue_policy 撤去 (DL_3 engine 全廃)。
    [Step 5A 2026-07-17] dl2_mb_ref / dl_2_latency_ewma / dl_2_latency_samples 撤去
    (DL_2 engine 全廃。消費者 _calc_dl_2_time_margin_ms は Phase 2 Step 3 で削除済)。
    """
    last_nnue_score_cp    : int   = 0
    last_nnue_mate_ply    : object = None  # [P1] 直前手 nnue の mate 距離 N (符号付き; 非詰みは None)
    prev_own_score_cp     : object = None  # [SF-TIME] 2手前の自分番 score_cp (falling-eval 用)
    council_agree_streak  : int   = 0      # [SF-TIME] DL_1==NNUE が連続一致した手数 (stability短縮用)
    last_child_agreement  : object = None  # [GP 2-axis] 子エンジン合意度 lag-1 (float 0..1 | None)
    last_bestmove_depth   : int   = 0
    # [Step 4D] dl_3_rescue_pending 撤去 (DL_3 engine 全廃)。
    # [WP3-6 2026-07-14 撤去] dl1_timeout_streak: 加算/読取ともに 0 (未実装のまま残置)
    dl_1_model_current    : str   = ""
    # [Step 5A 2026-07-17 撤去] dl2_mb_ref / dl_2_latency_ewma / dl_2_latency_samples:
    # DL_2 engine 全廃で read/write とも消滅 (自己較正 latency EWMA ごと撤去)。
    # 唯一の construction (EngineContext.__init__ L15165) は keyword 引数なので init 引数減は無害。
    # [WP3-6 2026-07-14 撤去] _rep_council_done: reader 消滅済み — gate 非機能
    # [疑問手解析] 勝勢到達ラッチ。自分視点 score が決着しきい値を超えたら True。
    # 立つと以降の手の stats に decided=True が刻まれる (ゲーム内で単調、戻らない)。
    decided_latched       : bool  = False
    # [GP サージ] 前手の GP 値。GP 変化量 (Δgame_phase) 算出に使用。
    # GP はゲームごとに一から累積されるため、ゲーム跨ぎの持ち越しは不要。
    last_game_phase               : object = None  # float | None
    # [STANCE 観測 v1] 攻め/受け分類用の前手保持。_append_move_record の
    # チョークポイントが読み書きする (per-path 計算と疎結合に保つため独立に
    # 持つ)。stance_last_game_phase は符号付き Δgame_phase 用、stance_last_score は score 推移用。
    # 局ごとにリセット (GP/score はゲーム内で完結)。
    stance_last_game_phase        : object = None  # float | None
    stance_last_score     : object = None  # int   | None
    # [Book council v6.0] 当該 go で council に食わせる定跡 seed 手と投票重み。
    # advisory/suspect 定跡ヒット時に _handle_go がセットし、_council_vote が
    # 第4の投票者として加算する。手番ごとに使い切り (go の冒頭で必ずクリア)。
    book_seed_move        : object = None  # str | None
    book_seed_weight      : float  = 0.0
    book_seed_trust       : str    = ""
    # [Step 5A 2026-07-17] [ARB1] nnue_2 on-demand 起動ラッチの説明ブロック撤去
    # (nnue_2 slot 全廃で対応 field も本 comment が説明する latch も消滅済)。
    # [OPP-ID v6.4] 相手系統検出。予測不一致手のみをサンプルとする (不一致駆動)。
    # opponent_id_pending : (base_tokens, nnue_pred, dl_pred) | None — one-shot。
    # 命中カウンタはゲーム内累積 (相手は 1 局を通じて同一という前提)。
    opponent_id_pending         : object = None
    opponent_id_nnue_hits       : int   = 0
    opponent_id_dl_hits         : int   = 0
    opponent_id_miss            : int   = 0
    opponent_id_samples         : int   = 0
    opponent_id_last_sample     : object = None   # "nnue"|"dl"|"miss"|None — per-move 記録用
    # [OPP-ID 名前断定] CSA Game_Summary の相手名がエンジン名欄にヒットした
    # 断定結果。"nnue"|"dl"|"hybrid"|None。設定中は検出器のサンプリング停止。
    opponent_id_forced_style    : object = None
    # [PH-EMIT] CSA 送信用 ponderhit score 退避 (one-shot)。L7572 の宣言厳格化規律に従い
    # reset() で書かれる属性は class field として明示宣言する (cold path で AttributeError
    # にならないよう class-level default を持たせる)。
    ponderhit_emit_ni     : object = None
    # [PONDER-CONF Phase 1] ponder 準備度の計測フィールド。
    # _CsaGame 層が _on_opponent_move で書き込む 6 フィールドと、
    # council 層が _handle_ponderhit 内で書き込む §2-D の 4 フィールド。
    # resa() で局ごとに None リセット。
    ponder_elapsed_s      : object = None  # float | None — ponder 経過秒 (FG 計測)
    ponder_hit            : object = None  # bool  | None — board_hit 判定結果
    ponder_sp             : object = None  # bool  | None — SP 設定されていたか
    ponder_miss_reason    : object = None  # str   | None — "usi-mismatch"|"board-mismatch"
    ponder_conf_level     : object = None  # str   | None — "conv"/"high"/"medium"/"low"
    ponder_conf_action    : object = None  # str   | None — Phase 2 cap 縮め結果
    # §2-D council 層由来 (ponder stop 処理で書き込み、FG が _move_relay_timeout で参照)
    ponder_move_dl        : object = None  # str   | None — DL の ponder bestmove
    ponder_move_nnue      : object = None  # str   | None — NNUE の ponder bestmove
    ponder_move_agreement : object = None  # bool  | None — DL==NNUE
    ponder_prefetch_corr  : object = None  # bool  | None — AUD-B prefetch 手 == DL ponder 手
    # [前例プリフェッチ] 第2予測応手 (DL PV 由来・主予測 ponder_move と割れたとき)。
    #   _start_ponder が主予測+これの 2 局面の Shogidb2 前例を温める (指されたら cache 命中)。
    ponder_alt_reply      : object = None  # str   | None
    # [REGIME v6.7] 局内確信軌道フィードバック (memory pyfamate-regime-native-design 参照)
    # CSM (confidence/sharpness/agree) の合成スカラ conviction を per-move 平滑し、
    # cruise/alert/crisis 3 regime 分類で eff_s/consensus_skip/Tonshi を変調する。
    # 寿命は局単位 (reset() で中立に戻す)。
    regime_conviction       : float  = 0.5    # EMA 平滑値 [0,1] (初期 0.5 中立)
    regime_conviction_prev  : float  = 0.5    # 前手 EMA (Collapse Δ 検出用)
    regime_label           : str    = _REGIME_ALERT   # cruise|alert|crisis — 下流変調キー
    regime_force_crisis     : bool   = False  # one-shot ラッチ (Collapse 後の次手強制 crisis)
    # [ZYFAMATE/MOMENTUM] 直前手の Momentum 値と tesuki_n。
    # Momentum は time_aggression の延長因子として消費 (負=危険→延長)。
    # tesuki_n は次手 Momentum 算出時の mate-threat 項に注入。
    last_momentum          : float  = 0.0
    last_tesuki_n          : object = None   # int | None
    last_sharpness         : object = None   # float | None — 前手 sharpness (time_aggression ⑦)
    last_dl_cont_changed   : bool   = False  # [KLEIST-2] 前手 DL Phase 2 で手が変わったか
    # [SP-STATS v6.6 2026-07] SP 計測用 per-move 診断データ (手確定時にレコードへ移し dict クリア)。
    sp_move_diag           : object = None   # dict | None

    def reset(self) -> None:
        """usinewgame 受信時にゲーム状態をリセット。
        dl_1_model_current はゲーム跨ぎで保持する (再ロード不要)。
        """
        self.last_nnue_score_cp    = 0
        self.last_nnue_mate_ply    = None  # [P1] 直前手 nnue の mate 距離
        self.prev_own_score_cp     = None  # [SF-TIME] falling-eval 用 (ゲーム跨ぎで持ち越さない)
        self.council_agree_streak  = 0     # [SF-TIME] stability短縮用 (ゲーム跨ぎで持ち越さない)
        self.last_child_agreement  = None  # [GP 2-axis]
        self.last_bestmove_depth   = 0
        # [Step 4D] dl_3_rescue_pending / dl_3_rescue_policy reset 撤去 (DL_3 engine 全廃)。
        self.decided_latched       = False  # [疑問手解析] 局ごとに勝勢ラッチを戻す
        self.last_game_phase               = None   # [GP サージ] 局ごとにリセット
        self.stance_last_game_phase        = None   # [STANCE] 局ごとにリセット
        self.stance_last_score     = None   # [STANCE] 局ごとにリセット
        self.book_seed_move        = None   # [Book council] 局ごとにクリア
        self.book_seed_weight      = 0.0
        self.book_seed_trust       = ""
        # [OPP-ID v6.4] 相手は局ごとに変わりうるため検出状態は全リセット。
        self.opponent_id_pending     = None
        self.opponent_id_nnue_hits   = 0
        self.opponent_id_dl_hits     = 0
        self.opponent_id_miss        = 0
        self.opponent_id_samples     = 0
        self.opponent_id_last_sample = None
        self.opponent_id_forced_style = None
        # [PONDER-CONF Phase 1] 局ごとにリセット。
        self.ponder_elapsed_s      = None
        self.ponder_hit            = None
        self.ponder_sp             = None
        self.ponder_miss_reason    = None
        self.ponder_conf_level     = None
        self.ponder_conf_action    = None
        self.ponder_move_dl        = None
        self.ponder_move_nnue      = None
        self.ponder_move_agreement = None
        self.ponder_prefetch_corr  = None
        self.ponder_alt_reply      = None
        self.ponderhit_emit_ni            = None  # [PH-EMIT] 局ごとにクリア
        # [REGIME v6.7] 局ごとに EMA / regime を中立リセット (前局を持ち越さない)
        self.regime_conviction       = 0.5
        self.regime_conviction_prev  = 0.5
        self.regime_label           = _REGIME_ALERT
        self.regime_force_crisis     = False
        # [ZYFAMATE/MOMENTUM] 局ごとにリセット
        self.last_momentum          = 0.0
        self.last_tesuki_n          = None
        self.last_sharpness         = None
        self.last_dl_cont_changed   = False
        self.sp_move_diag           = None  # [SP-STATS v6.6]


@dataclasses.dataclass
class Dl1FetchState:
    """_run_council_search のキャッシュミス時に生成される DL_1 fetch スレッド共有状態。

    フィールド
    ----------
    result     : fetch_dl_policy の戻り値 6-tuple、未完了なら None
    t_start    : dl_1_lock 取得後の fetch 開始時刻 (time.perf_counter())、未記録なら 0.0
    t_end      : fetch 完了時刻 (time.perf_counter())、未完了なら 0.0
    t_lock_wait: dl_1_lock 待機時間 [ms] (診断用)
    """
    result     : object = None   # (policy, mate, actual_gap, pv_lines, depth_best, score_hist) | None
    t_start    : float  = 0.0
    t_end      : float  = 0.0
    t_lock_wait: float  = 0.0
    cont_changed: bool  = False  # [KLEIST-2] Phase 2 bestmove が Phase 1 と異なったか
    # [PATCH-DL2-PH1-EVENT 2026-07-07b] Phase 1 完了通知 Event。
    # _dl_1_fetch_thread_fn が Phase 1 (result 書き込み + dl_1_lock 解放) 完了時に
    # set する。DL_2 (cache-miss 経路) は dl_thread.join() の代わりにこれを待つ —
    # Phase 2 (継続 20 万ノード探索) の完走を待たずに DL_2 を起動できる。
    # 例外経路でも呼び出し側 wrapper の finally が必ず set する (永久 wait 防止)。
    phase1_done : object = dataclasses.field(default_factory=threading.Event)


@dataclasses.dataclass
class Dl1FetchParams:
    """_dl_1_fetch_thread_fn に渡す「読み取り専用」入力パラメータ群。

    _dl_2_fetch_thread_fn の Dl2FetchParams と対称な設計。
    closure 参照を排除し、DL_1 fetch スレッド関数をトップレベル化するために導入。
    すべてのフィールドはスレッド起動前に確定した値であり、スレッドから
    書き込まれることはない（書き込みは Dl1FetchState 経由）。

    フィールド
    ----------
    ctx           : EngineContext — dl_1 / prefetch.dl_1_lock を参照
    n             : fetch_dl_policy に渡す候補手数
    nodes         : fetch_dl_policy に渡すノード数
    dl_timeout    : DL_1 fetch タイムアウト [秒]
    dl_gap_min    : gap_min 閾値 [cp]
    eff_s         : 有効残り時間 [秒]
    dl_time_min_ms: _dl_time_min_ms の snapshot (モジュール global 参照を排除)
    position      : 探索対象局面文字列 (ctx.current_position の snapshot)
    """
    ctx           : object   # EngineContext
    n             : int
    nodes         : int
    dl_timeout    : float
    dl_gap_min    : float
    eff_s         : float
    dl_time_min_ms: float
    position      : str


@dataclasses.dataclass
class MateResult:
    """_run_mate_solver_thread の out-param ホルダ。

    _run_mate_solver_thread をスレッドに渡し、join() 後に参照する。
    GIL のおかげで str/None の単純代入は原子的だが、必ず join() 後に読むこと。

    フィールド
    ----------
    result   : \"mate\" / \"nomate\" / \"busy\" / None
    best_move: 詰み手順先頭手 (str) or None
    """
    result   : object = None   # "mate" | "nomate" | "timeout" | "busy" | None
    best_move: object = None   # str | None
    # [MATE-PROTO] checkmate 行由来 (= ソルバーによる証明) なら True。
    # bestmove/info 行由来の "nomate" は時間切れと区別できないため False のまま。
    proof    : object = False
    # [13-6 提案B] checkmate <m1> <m2> ... <mN> の全手順 (m1..mN、= best_move も
    # 含む)。result=="mate" のときのみ非 None。_store_mate_pv 経由で ctx.mate_pv
    # へ渡し、実戦がその後さらに進んでも手順の続きを再利用できるようにする
    # (_zf_digger_verify と同型の prefix 一致再利用。§13-2/13-3 参照)。
    pv_moves : object = None   # list[str] | None


# ---------------------------------------------------------------------------
# EngineConfig — グループ A / E / F の config 値を一元管理する dataclass。
# 段階的移行（B1実装準備メモ §3-3）:
#   グループ A（純粋ロジック閾値）と E（GP計算）、F（ロギング）のみを収録。
#   グループ B（タイムアウト系）・C（起動設定）・D（DL_3）は実機回帰テスト整備後に追加する。
# 使い方:
#   ctx.cfg.game_phase_handover_threshold  など ctx 経由でアクセスする。
#   setoption / SPSA 書き換えは ctx.cfg.xxx = val の形で行う（グループ B 移行時に対応）。
# ---------------------------------------------------------------------------

# ---------- 【最適化 2-1】TimeAggressionState ----------

@dataclasses.dataclass
class TimeAggressionState:
    """Time Aggression 関連の動的状態を一元管理する dataclass。

    従来の 7 個のモジュールレベル global 変数を集約し、EngineContext の
    属性として保持する。

    master      : _time_dyn.time_aggression (毎手 _compute_go_time_dynamics が更新)
    dl          : _time_aggression_dl (静的サブノブ)
    nnue        : _time_aggression_nnue
    rescue      : _time_aggression_rescue
    dl_dyn      : _time_dyn.time_aggression_dl_dyn (動的サブノブ)
    nnue_dyn    : _time_dyn.time_aggression_nnue_dyn
    rescue_dyn  : _time_dyn.time_aggression_rescue_dyn
    base        : _time_aggression_base (config 由来、不変)
    """
    master:     float
    dl:         float
    nnue:       float
    rescue:     float
    dl_dyn:     float
    nnue_dyn:   float
    rescue_dyn: float
    base:       float
    _resolve_ta_fn: object = dataclasses.field(default=None, repr=False)

    @classmethod
    def from_config(cls, base: float, resolve_ta_fn) -> "TimeAggressionState":
        dl     = resolve_ta_fn(_K_TIME_AGGRESSION_DL,     base)
        nnue   = resolve_ta_fn(_K_TIME_AGGRESSION_NNUE,   base)
        rescue = resolve_ta_fn(_K_TIME_AGGRESSION_RESCUE, base)
        return cls(
            master=base, dl=dl, nnue=nnue, rescue=rescue,
            dl_dyn=dl, nnue_dyn=nnue, rescue_dyn=rescue,
            base=base, _resolve_ta_fn=resolve_ta_fn,
        )

    def reset_to_static(self) -> None:
        """局開始/終了時に静的値へリセットする。"""
        resolve = self._resolve_ta_fn
        self.master = self.base
        self.dl     = resolve(_K_TIME_AGGRESSION_DL,     self.base)
        self.nnue   = resolve(_K_TIME_AGGRESSION_NNUE,   self.base)
        self.rescue = resolve(_K_TIME_AGGRESSION_RESCUE, self.base)
        self.dl_dyn     = self.dl
        self.nnue_dyn   = self.nnue
        self.rescue_dyn = self.rescue

    def writeback_from_dynamics(self, td) -> None:
        """_compute_go_time_dynamics の結果を書き戻す。"""
        self.master     = td.time_aggression
        self.dl_dyn     = td.time_aggression_dl
        self.nnue_dyn   = td.time_aggression_nnue
        self.rescue_dyn = td.time_aggression_rescue

# ---------- TimeAggressionState ここまで ----------


