class _UVote(enum.Enum):
    DL1 = enum.auto(); DL2 = enum.auto(); DL3 = enum.auto(); NNUE = enum.auto()
class _UCache(enum.Enum):
    DL_POLICY = enum.auto(); DL3 = enum.auto(); MATE_PV = enum.auto()
class _UPref(enum.Enum):
    UNCOND = enum.auto(); GATED = enum.auto(); SIMPLE = enum.auto()

@dataclasses.dataclass(frozen=True)
class _UVar:
    name: str; voters: tuple; dl3_proxy: bool; dl_veto: bool
    use_mate_solver: bool; reserve_dl1_budget: bool; cache: object; prefetch: object
    apply_boost: bool; relay_reduced_eff_s: bool; relay_pv_head: bool; label: str
    # [RF-1 2026-07-15] ponderhit 経路スイッチ。ponderhit は setup/dispatch/relay/
    # finalize の各段に専用分岐を持つ (4-way: mate_skip/stale/cache_hit/cache_miss)。
    # 17 フラグ分割案 (偵察 §2.4.2) は常に共起する = 死んだ構成空間を作るため 1 値に集約。
    ph: bool = False

_UV_COUNCIL = _UVar("council", (_UVote.DL1, _UVote.DL2, _UVote.NNUE), True, False,
                    True, True, _UCache.DL_POLICY, _UPref.UNCOND, True, True, True, "council")
_UV_ENDGAME = _UVar("endgame", (_UVote.NNUE,), False, True,
                    True, False, _UCache.MATE_PV, _UPref.SIMPLE, False, False, False, "endgame")
# [RF-1 2026-07-15] ponderhit 変種。voters は cache_hit council 時の上限集合 —
# cache_miss では dl キャッシュ/スレッド不在により DL 票は自然に空票になる。
# dl3_proxy=False (relay full PV 非保持)、dl_veto=False (endgame veto は PH lane が
# ctx.endgame_mode で直接呼ぶ)、use_mate_solver=False (PH の mate は MPON/mate_skip 側)、
# cache/prefetch は PH lane では dispatch/finalize 専用実装が担うため参照されない。
_UV_PONDERHIT = _UVar("ponderhit", (_UVote.DL1, _UVote.DL2, _UVote.NNUE), False, False,
                      False, False, _UCache.DL_POLICY, _UPref.UNCOND, True, False, False,
                      "ponderhit", ph=True)

class _NnueGuard(enum.Enum):
    ALIVE = enum.auto(); HANDLED = enum.auto()

def _ensure_nnue_or_recover(ctx, *, phase, go_clock, eff_s, t_go_start, label):
    """[SEAM-1 / RECOVERY-HUB] nnue_1 dead 復帰を _recover(GO_ENTRY) へ委譲。
    旧: 3 種 deadline 式 + sync→emergency→wait_revive→resign カスケード。
    新: _recover(nnue_1, GO_ENTRY) が sync→wait_revive→emergency→resign 統一順序
        (spec §1.2 の cascade 順序統一 — 意図的挙動変更)。
    label/phase/eff_s/t_go_start は現状 telemetry のみ (将来の per-caller 特化用に残置)。
    """
    if ctx.nnue_1._alive:
        return _NnueGuard.ALIVE
    r = _recover(ctx.nnue_1, reason=RecoverReason.GO_ENTRY,
                 clock=go_clock, ctx=ctx)
    if r.kind is RecoverKind.SYNC_RESTARTED:
        return _NnueGuard.ALIVE
    return _NnueGuard.HANDLED

