def _handle_setup(ctx, line):
    """[SETUP] stdin から "setup" — デバイス依存キー専用 SPSA を開始。

    engine.exe を起動してそのまま "setup" と入力するだけで動作する
    (引数付きも可: "setup --iterations 50 --max-hours 12")。
    _handle_spsa と同じくバックグラウンドスレッドで _spsa_cli(setup_mode=True)
    を走らせるため USI ループはブロックしない。setup_state.txt があれば
    _spsa_cli 内で自動 resume、結果は setup_config.txt へ出力される。
    対局進行中 (usinewgame 済み) は全資源占有のため拒否する
    (tournament と同じガード — spsa より安全側に倒す)。
    """
    if _reject_if_session_active("setup"):
        return
    _flog("[SETUP] 'setup' command received — starting device-dependent tuning")
    print("info string [setup] セットアップ (環境依存キーの調整 → setup_config.txt) を開始しました", flush=True)

    _typed_args = line.split()[1:]   # "setup --iterations 50" の引数を転送

    def _run():
        _saved = sys.argv[:]
        # setup_state.txt の自動 resume は _spsa_cli(setup_mode=True) 側が行う。
        sys.argv = [sys.argv[0], "setup"] + _typed_args
        try:
            _spsa_cli(setup_mode=True)
        except SystemExit:  # [SILENT-OK RF-4] sub-CLI SystemExit swallow (親プロセスを落とさない)
            pass
        except Exception as e:
            _flog("[SETUP] tuning error: %s" % e)
        finally:
            sys.argv = _saved
    t = _spawn('setup-tuner', _run, start_now=False)
    t.start()


def _handle_teacher(ctx, line):
    """stdin から 'teacher' — packed-sfen から model.pt の学習を実行する。
    learn --psv に委譲。引数省略時は既定フォルダ (C:\\Shogi\\psv) を使用。
    teacher [<path.bin or dir>] [epochs=N] [batch=N] [lr=F] [steps=N]
    [ARCH-V3] ver=3 で認識・評価 2 段分離モデル (評価は特徴平面 — 推奨):
    teacher ver=3 ch=64 blocks=5 gray=1
    [DISTILL] 学習済みモデルを教師に小型化 (蒸留 — 精度を残して軽量化):
    teacher ver=3 ch=32 blocks=3 distill=model.pt [distill-mix=0.7]"""
    if _reject_if_session_active("teacher"):
        return
    # [PATH-FIX 2026-07-05] 空白入りパス対応: "..." で囲まれたトークンを 1 個として扱う
    args = [a.strip('"') for a in re.findall(r'"[^"]*"|\S+', line)][1:]
    psv_path = None
    learn_args = []
    for a in args:
        if "=" in a:
            k, v = a.split("=", 1)
            if k in ("epochs", "batch", "lr", "steps", "workers",
                     "img", "ch", "blocks", "ver", "wr-slope", "gray",
                     "gp-fuse", "distill", "distill-mix"):
                # 解像度/構成/WR傾き/gray/GP融合/蒸留 を転送
                learn_args.extend(["--" + k, v])
        elif psv_path is None:
            psv_path = a
    if psv_path is None:
        psv_path = _TEACHER_DEFAULT_PSV_DIR
    # [PATH-FIX 2026-07-05] 空白入りパス (例 E:\New folder) が learn 側の空白分割で
    # 崩れないようクォートして渡す (_handle_learn はクォート対応の分割を行う)
    learn_line = 'learn --psv "%s"' % psv_path.strip('"')
    if learn_args:
        learn_line += " " + " ".join(learn_args)
    _handle_learn(ctx, learn_line)


def _handle_arb(ctx, line):
    """[ARB-ONE-SHOT 2026-07-17] stdin 'arb' — arbiter.onnx 一括生成 (コンソール一言で全段)。

    arb                 = 全段: synth (互角局面集 txt→不一致サンプル) → label (オラクル)
                          → train (→ arbiter.onnx + arbiter_head.npz)。段ごとに完了済みは
                          skip (samples ≥ 10,000 行で synth skip / labeled ≥ samples で
                          label skip)。'arb force' で全段強制再実行。
    arb synth|label|train [引数...] = 単段実行 (引数は各 main へ素通し)。
    arb temp            = C:\\temp の互角局面集 (*.txt) で全段 (投げ込みフォルダ。synth は skip せず実行)。
    arb status          = 各段の成果物 (行数/サイズ) を表示。
    配置は出力で完結: Pyfamate は artefact 検出で次局から live (boolean 全廃)、
    Cyfamate は CYFAMATE_DL_MODEL=<arbiter.onnx> を指すだけ (native ORT 経路が点灯)。"""
    if _reject_if_session_active("arb"):
        return
    import time as _time
    toks = [t.strip('"') for t in re.findall(r'"[^"]*"|\S+', line)][1:]
    force = "force" in toks
    toks = [t for t in toks if t != "force"]
    # [2026-07-17] "temp" = C:\temp の棋譜で全段 (投げ込みフォルダ運用。synth は skip せず必ず実行)
    sub = toks[0] if toks and toks[0] in ("synth", "label", "train", "status", "all", "temp") else "all"
    rest = toks[1:] if toks and toks and toks[0] == sub else toks

    samples = _ARBITER_SAMPLES_PATH
    labeled = os.path.join(_BASE_DIR, "arbiter_labeled.jsonl")

    def _nl(p):
        try:
            with open(p, "rb") as fh:
                return sum(1 for _ in fh)
        except OSError:
            return 0

    def _label_stale():
        """label 再実行の要否。行数比較だけだと空振り synth の残骸 labeled が
        『labeled ≥ samples(0)』で誤 skip する — mtime も見て samples の方が
        新しければやり直す (2026-07-17 の 0 サンプル事故の再発防止)。"""
        if not os.path.isfile(labeled):
            return True
        if _arb_count_current(labeled) < _arb_count_current(samples):
            return True
        try:
            return os.path.getmtime(samples) > os.path.getmtime(labeled)
        except OSError:
            return True

    if sub == "status":
        print("[arb] samples: %d 行 (現行版 %d) (%s)" % (_nl(samples), _arb_count_current(samples), samples))
        print("[arb] labeled: %d 行 (現行版 %d) (%s)" % (_nl(labeled), _arb_count_current(labeled), labeled))
        for fn in ("arbiter.onnx", "arbiter_head.npz"):
            p = os.path.join(_svonnx_here(), fn)
            print("[arb] %s: %s" % (fn, ("%d bytes" % os.path.getsize(p))
                                    if os.path.isfile(p) else "無し"))
        return

    if _IS_FROZEN:
        # [ARB-FROZEN 2026-07-17] frozen exe はインプロセス実行禁止 (torch/numpy 等の
        # 巨大依存は exe 非同梱 — NO-BUNDLE 設計)。learn と同じ委譲様式で、段ごとに
        # system Python + Pyfamate.py の CLI サブコマンドへ subprocess 委譲する。
        engine_dir = os.path.dirname(os.path.abspath(sys.executable))
        script = None
        for name in ("Pyfamate.py", "pyfamate.py"):
            p = os.path.join(engine_dir, name)
            if os.path.exists(p):
                script = p
                break
        if not script:
            print("[arb] Pyfamate.py が exe と同じフォルダに必要です", flush=True)
            return
        pycmd = _ensure_system_python()
        if not pycmd:
            print("[arb] system Python を用意できませんでした", flush=True)
            return
        # [ARB-PREFLIGHT 2026-07-17] Pyfamate.py は並行セッションが編集中のことがある。
        # 委譲実行前に構文チェックし、赤い中間状態なら意味不明な NameError でなく
        # 明示メッセージで止める (Step 6B 編集中に arb が走って即死した実例対策)。
        try:
            _pfrc = subprocess.call(pycmd + ["-m", "py_compile", script],
                                    cwd=engine_dir, stdout=subprocess.DEVNULL)
        except Exception:
            _pfrc = 0   # プリフライト自体の失敗は本走行に委ねる
        if _pfrc != 0:
            print("[arb] Pyfamate.py が現在コンパイル不能 (並行編集の中間状態の可能性)。"
                  " 数分待って再実行してください。", flush=True)
            return
        def _run_stage(st):
            print("[arb] → %s" % " ".join(st), flush=True)
            try:
                rc = subprocess.call(pycmd + [script] + st, cwd=engine_dir)
            except Exception as _se:
                print("[arb] 委譲起動失敗: %r" % _se, flush=True)
                return False
            if rc != 0:
                print("[arb] %s 失敗 (rc=%d) — 中断" % (st[0], rc), flush=True)
                return False
            return True

        # 逐次実行 + 実行時判定 (label の要否は synth 完了「後」の件数で決める)
        t0f = _time.time()
        if sub in ("all", "synth", "temp"):
            n_s = _arb_count_current(samples)   # [ARB-ORACLE-V2] 旧版汚染行は件数に数えない
            if sub in ("synth", "temp") or force or n_s < 10000:
                _kif_extra = ["--sfens", r"C:\temp"] if sub == "temp" else []
                if not _run_stage(["arbiter-synth"] + _kif_extra
                                  + (rest if sub == "synth" else [])):
                    return
            else:
                print("[arb] synth skip (samples=%d 行 — 'arb force' で強制)" % n_s)
        if sub in ("all", "label", "temp"):
            if sub in ("label", "temp") or force or _label_stale():
                if force and os.path.isfile(labeled):
                    os.replace(labeled, labeled + ".bak")
                    print("[arb] labeled を退避: %s.bak" % labeled)
                if not _run_stage(["arbiter-label"] + (rest if sub == "label" else [])):
                    return
            else:
                print("[arb] label skip (labeled が samples より新しく件数も充足)")
        if sub in ("all", "train", "temp"):
            if not _run_stage(["arbiter-train"] + (rest if sub == "train" else [])):
                return
            # 成功宣言の前に成果物を実検証 (教師0行で train が黙って return しても
            # rc=0 のため、「全段完了」と誤報した 2026-07-17 の事故の再発防止)。
            _ok = True
            for fn in ("arbiter.onnx", "arbiter_head.npz"):
                p = os.path.join(_svonnx_here(), fn)
                if not (os.path.isfile(p) and os.path.getmtime(p) >= t0f - 60):
                    print("[arb] 失敗: %s が生成されていない (教師データ不足の可能性 — "
                          "'arb status' で各段の件数を確認)" % fn, flush=True)
                    _ok = False
            if not _ok:
                return
            print("[arb] 全段完了 (%.0f 秒)" % (_time.time() - t0f))
            print("[arb] Pyfamate: artefact 検出で次局から live (操作不要)")
            print("[arb] Cyfamate: set CYFAMATE_DL_MODEL=%s"
                  % os.path.join(_svonnx_here(), "arbiter.onnx"))
        return

    t0 = _time.time()
    try:
        if sub in ("all", "synth", "temp"):
            n_s = _arb_count_current(samples)   # [ARB-ORACLE-V2] 旧版汚染行は件数に数えない
            if sub in ("synth", "temp") or force or n_s < 10000:
                _kif_extra = ["--sfens", r"C:\temp"] if sub == "temp" else []
                sv_arbiter_synth_main(_kif_extra + (rest if sub == "synth" else []))
            else:
                print("[arb] synth skip (samples=%d 行 — 'arb force' で強制)" % n_s)
        if sub in ("all", "label", "temp"):
            if sub in ("label", "temp") or force or _label_stale():
                if force and os.path.isfile(labeled):
                    os.replace(labeled, labeled + ".bak")
                    print("[arb] labeled を退避: %s.bak" % labeled)
                sv_arbiter_label_main(rest if sub == "label" else [])
            else:
                print("[arb] label skip (labeled が samples より新しく件数も充足)")
        if sub in ("all", "train", "temp"):
            sv_arbiter_train_main(rest if sub == "train" else [])
            _ok = True
            for fn in ("arbiter.onnx", "arbiter_head.npz"):
                p = os.path.join(_svonnx_here(), fn)
                if not (os.path.isfile(p) and os.path.getmtime(p) >= t0 - 60):
                    print("[arb] 失敗: %s が生成されていない (教師データ不足の可能性 — "
                          "'arb status' で各段の件数を確認)" % fn, flush=True)
                    _ok = False
            if not _ok:
                return
            print("[arb] 全段完了 (%.0f 秒)" % (_time.time() - t0))
            print("[arb] Pyfamate: artefact 検出で次局から live (操作不要)")
            print("[arb] Cyfamate: set CYFAMATE_DL_MODEL=%s"
                  % os.path.join(_svonnx_here(), "arbiter.onnx"))
    except (KeyboardInterrupt, SystemExit, MemoryError):
        raise
    except Exception as _ae:
        print("[arb] error: %r" % _ae, flush=True)
        _flog(f"[arb] {_ae!r}")


def _handle_replay(ctx, line):
    """[REPLAY 2026-07-05] stdin/CLI 'replay': stats.txt の per-move レコード
    (ts 付き) から端末 UI (_sr_render_board) を局後再生する。

    replay [<stats path>] [game=N] [speed=F]
      game  = 末尾から N 局目 (既定 1 = 最新局)
      speed = 再生倍速 (既定 10。1 で実対局と同テンポ、手間隔の上限 5s)"""
    toks = [t.strip('"') for t in re.findall(r'"[^"]*"|\S+', line)][1:]
    path, game_back, speed = _STATS_PATH, 1, 10.0
    for t in toks:
        if "=" in t:
            k, v = t.split("=", 1)
            try:
                if k == "game":
                    game_back = max(1, int(v))
                elif k == "speed":
                    speed = max(0.01, float(v))
            except ValueError:
                print(f"[replay] 引数を解釈できません: {t}", flush=True)
                return
        else:
            path = t
    try:
        raw = open(path, encoding="utf-8", errors="replace").read().splitlines()
    except OSError as e:
        print(f"[replay] stats を開けません: {e}", flush=True)
        return
    games, cur = [], []
    for ln in raw:
        if ln.startswith("#GAME "):
            games.append(cur)
            cur = []
        else:
            cur.append(ln)
    games.append(cur)
    games = [g for g in games if any(ln.lstrip().startswith("{") for ln in g)]
    if not games:
        print("[replay] 再生可能な対局が見つかりません", flush=True)
        return
    recs = []
    for ln in games[-min(game_back, len(games))]:
        try:
            r = json.loads(ln)
        except Exception:
            continue
        mv = r.get("bestmove") or r.get("move") or r.get("council_winner")
        if isinstance(mv, str) and re.match(r"^[1-9a-zA-Z*+]{4,5}$", mv):
            recs.append((r, mv))
    if not recs:
        print("[replay] 指し手レコードがありません (旧 stats は ts 無しでも再生可)",
              flush=True)
        return
    print(f"[replay] {len(recs)} 手を再生します (speed=x{speed:g})", flush=True)
    moves, prev_ts = [], None
    for r, mv in recs:
        ts = r.get("ts")
        _dt = ((ts - prev_ts) if (prev_ts is not None
                                  and isinstance(ts, (int, float))) else 1.0)
        if moves:
            time.sleep(_clamp(_dt, 0.05, 5.0) / speed)
        if isinstance(ts, (int, float)):
            prev_ts = ts
        moves.append(mv)
        try:
            bd = _board_for_position("position startpos moves " + " ".join(moves))
        except Exception as _be:
            print(f"[replay] 盤再構築に失敗 ({len(moves)}手目 {mv}: {_be!r}) — 中断",
                  flush=True)
            return
        wr = None
        for k in ("score_cp", "cp", "nnue_score_cp", "dl_score_cp"):
            v = r.get(k)
            if isinstance(v, (int, float)):
                wr = _cp_to_winrate(v, _SR_WR_SLOPE) * 100.0
                break
        # [FIX-WR-POV 2026-07-09] rec の score は指した側 (自手番) 視点 (per-move
        # 規約)。評価バーは先手POV固定 (左=後手/右=先手) のため、後手の手
        # (偶数手目; replay は position startpos 固定なのでパリティで確定) は
        # 反転して渡す。
        if wr is not None and len(moves) % 2 == 0:
            wr = 100.0 - wr
        _tstr = (time.strftime("%H:%M:%S", time.localtime(ts))
                 if isinstance(ts, (int, float)) else "")
        hdr = f"── {len(moves)}手目 {mv}" + (f"  [{_tstr}]" if _tstr else "")
        try:
            print(_sr_render_board(bd, winrate=wr, header=hdr), flush=True)
        except Exception as _re:
            print(f"[replay] 描画失敗 (継続): {_re!r}", flush=True)
    print("[replay] 終了", flush=True)


