def _handle_dumpparams(ctx, line):
    """[D-2] 全 SPSA パラメータの実効値を 1 行 JSON で出力する診断コマンド。
    setoption 化の検証に使う: config 起動と setoption 注入で全キー bit 一致を確認。"""
    try:
        params = _spsa_default_params()
        dump = {p.name: (int(p.value) if p.is_int else round(p.value, 6)) for p in params}
        print("info string dumpparams " + json.dumps(dump, ensure_ascii=False), flush=True)
        _flog("[DUMPPARAMS] %d params dumped" % len(dump))
    except Exception as e:
        print("info string dumpparams error: %s" % e, flush=True)
        _flog("[DUMPPARAMS] error: %r" % e)


EXACT_DISPATCH = {
    "usi":        _handle_usi,
    "isready":    _handle_isready,
    "usinewgame": _handle_usinewgame,
    "stop":       _handle_stop,
    "quit":       _handle_quit,
    "spsa":       _handle_spsa,
    "setup":      _handle_setup,
    "game":       _handle_game,
    "match":      _handle_match,
    "grid":       _handle_grid,
    "fit":        _handle_fit,
    "tournament": _handle_tournament,
    "teacher":    _handle_teacher,
    "arb":        _handle_arb,     # [ARB-ONE-SHOT] arbiter.onnx 一括生成 (synth→label→train)
    "learn":      _handle_learn,   # [VISION] 盤面ビジョンモデル学習 (C:\kif + PV末端)
    "makebook":   _handle_makebook,
    "dlp":        _handle_dlp,
    "replay":     _handle_replay,  # [REPLAY] stats.txt から局後 UI 再生
    "dumpparams": _handle_dumpparams,
}

# [CONSOLE] 先頭トークン一致 — 引数付きコンソールコマンド用。
# EXACT_DISPATCH は行全体の完全一致なので "fit game_phase:iters=600" や
# "game_phase_fit C:\kif iters=500" (docstring の用例) が unknown command に落ちていた。
# PREFIX_DISPATCH は startswith のため "game_phase" が "go..." 等と曖昧になる恐れが
# あり使えない。トークン一致なら衝突しない。
TOKEN_DISPATCH = {
    "fit":        _handle_fit,
    "tournament": _handle_tournament,
    "teacher":    _handle_teacher,
    "arb":        _handle_arb,     # [ARB-ONE-SHOT] "arb force" / "arb train --epochs 16" 等
    "setup":      _handle_setup,   # [SETUP] "setup --iterations 50" 等の引数付き
    # 引数付き ("game skip" / "spsa skip" / "grid skip" 等) を認識するため追加。
    # EXACT_DISPATCH の完全一致は引数なし単体で機能するが、TOKEN_DISPATCH は
    # 先頭トークン一致なので "game skip" のように後続トークンがある場合もここで捕捉する。
    "game":       _handle_game,
    # [MATCH-PARITY 2026-07-10] "match skip" / "match ponder" 等の引数付きが
    # EXACT_DISPATCH (完全一致) を外れて unknown command に落ちていた ("game skip"
    # は動くのに match だけ死ぬ齟齬)。本番当日に prereq (DLP/Setup) を skip する
    # 唯一の経路なので必須。
    "match":      _handle_match,
    "spsa":       _handle_spsa,
    "grid":       _handle_grid,
    "learn":      _handle_learn,   # [VISION] "learn --kif D:\x" 等の引数付き
    "makebook":   _handle_makebook,
    "dlp":        _handle_dlp,
    "replay":     _handle_replay,  # [REPLAY] "replay game=2 speed=5" 等の引数付き
}


def _is_bare_sfen(line: str) -> bool:
    """先頭トークンにスラッシュが 8 個あれば SFEN 盤面部と判定する。
    9x9 将棋盤は段区切りが必ず 8 本あり、既存 USI/CLI コマンドは
    スラッシュを一切含まないため衝突しない。"""
    first = line.split()[0] if line.split() else ""
    return first.count("/") == 8

PREFIX_DISPATCH = [
    ("setoption",  _handle_setoption),
    ("position",   _handle_position),
    ("go ponder",  _handle_go_ponder),
    ("go",         _handle_go),
    ("ponderhit",  _handle_ponderhit),
    ("gameover",   _handle_gameover),
]

def _dispatch(ctx, line):
    """1 行の USI コマンドを適切なハンドラに振り分ける。"""
    handler = EXACT_DISPATCH.get(line)
    if handler:
        handler(ctx, line)
        return
    for prefix, handler in PREFIX_DISPATCH:
        if line.startswith(prefix):
            handler(ctx, line)
            return
    handler = TOKEN_DISPATCH.get(line.split()[0])
    if handler:
        handler(ctx, line)
        return
    # 生SFEN自動検出: 先頭トークンにスラッシュ8個 → ファイル出力（stdout無音）
    if _is_bare_sfen(line):
        _handle_bare_sfen(ctx, line)
        return
    _flog(f"unknown command: {line!r}")

# ============================================================
# Tuner CLI  (--report / --spsa)
# ============================================================
# hybrid_tuner.py / hybrid_tuner_v2_18.py を廃止し、本ファイルに統合。
# 使い方:
#   python engine.py --report             サマリー + lock-wait 分析
#   python engine.py --spsa               SPSA 自動調整
#   末尾にパスを追加可: python ... --report [path/to/stats.txt]
# 引数なし / 不明な引数 → 従来通り USI エンジンとして起動 (動作変化なし)。
# ホットパス (_run_council_search 等) への影響: ゼロ。


def _stats_avg(xs):
    """per-move レコードリストの数値フィールドの平均。空なら 0.0。"""
    return (sum(xs) / len(xs)) if xs else 0.0


def _stats_rate(recs, n_games):
    """_ab_compare_stats 用の統計サマリーを返す。"""
    ovs = [1 for m in recs if m.get("council_override")]
    phs = [1 for m in recs if m.get("prefetch_hit")]
    pns = [1 for m in recs if m.get("dl_cache_src") == "ponder"]
    dlu = [1 for m in recs if m.get("dl_used")]
    return {
        "n": len(recs),
        "games": n_games,
        "override_rate": (len(ovs) / len(recs)) if recs else 0.0,
        "prefetch_rate": (len(phs) / len(dlu)) if dlu else 0.0,
        "ponder_rate":   (len(pns) / len(dlu)) if dlu else 0.0,
        "avg_eff_s":   _stats_avg([float(m.get("eff_s",    0.0) or 0.0) for m in recs]),
        "avg_nnue_cp": _stats_avg([float(m.get("nnue_score_cp", 0.0) or 0.0) for m in recs]),
    }


def _tuner_percentile(sorted_vals, p):
    """線形補間なし版パーセンタイル (標準ライブラリのみ)。"""
    if not sorted_vals:
        return None
    idx = _clamp(int(len(sorted_vals) * p / 100), 0, len(sorted_vals) - 1)
    return sorted_vals[idx]


def _tuner_rate(num, den):
    return round(num / den, 3) if den else None


def _tuner_fmt_rate(r):
    return "N/A" if r is None else f"{r:.1%}"


def _tuner_load_games(path):
    """
    stats.txt をゲーム単位で読み込み、ゲームのリストを返す。
    各ゲームは {"meta": {...}, "moves": [...]} の dict。
    moves は出現順 (ply 昇順) を保持する。

    _tuner_load_records とは異なりゲーム境界を保持するため、
    「同一ゲーム内の直近 N 手」を参照する分析に使用する。
    """
    games = []
    try:
        with open(path, encoding="utf-8") as f:
            for raw in f:
                raw = raw.strip()
                if not raw:
                    continue
                try:
                    game = json.loads(raw)
                except json.JSONDecodeError:
                    continue
                # [STATS-UNIFIED] stats.txt には #GAME 境界行 (非 JSON) と
                # per-move 行 (moves 配列を持たない) が混在する。ゲーム単位の
                # まとめレコード (moves キーを持つ dict) のみ採用する。
                if not (isinstance(game, dict) and "moves" in game):
                    continue
                # [STATS-SALVAGE-VOID 2026-07-09] infra-void 局 (偽 result="draw")
                # は消費しない — salvage 時タグ (infra_void) / reason 直書きの両形。
                if (game.get("infra_void")
                        or game.get("reason") in _SPSA_INFRA_VOID_REASONS):
                    continue
                games.append(game)
    except FileNotFoundError as _e:
        _flog(f"[ignored] _tuner_load_games: {_e!r}")
    return games


def _tuner_load_records(path):
    """
    stats.txt を読み込み、per-move レコードのリストを返す。
    formula.version でフィルタは行わず全レコードを返す。
    """
    records = []
    n_games = 0
    version_counter = {}

    try:
        with open(path, encoding="utf-8") as f:
            for raw in f:
                raw = raw.strip()
                if not raw:
                    continue
                try:
                    game = json.loads(raw)
                except json.JSONDecodeError:
                    continue
                # [STATS-UNIFIED] #GAME 行・per-move 行は読み飛ばし、ゲーム単位の
                # まとめレコード (moves キーを持つ dict) のみを集計対象とする。
                if not (isinstance(game, dict) and "moves" in game):
                    continue
                # [STATS-SALVAGE-VOID 2026-07-09] infra-void 局は集計から除外。
                if (game.get("infra_void")
                        or game.get("reason") in _SPSA_INFRA_VOID_REASONS):
                    continue
                n_games += 1
                ver = game.get("formula", {}).get("version", "unknown")
                version_counter[ver] = version_counter.get(ver, 0) + 1
                for move in game.get("moves", []):
                    move["_game_result"] = game.get("result", "unknown")
                    move["_formula_version"] = ver
                    # [Step 7C 2026-07-17] v6.7 dual-read 撤去 (formula version v7.0 単路化)。
                    # 旧 pre-v6.7 stats.txt からの regime field 剥がしは廃止。
                    records.append(move)
    except FileNotFoundError:
        print(f"[ERROR] ファイルが見つかりません: {path}", file=sys.stderr)
        sys.exit(1)

    return records, n_games, version_counter


def _tuner_report(records, n_games, version_counter):
    """--report: サマリー + lock-wait 分析 (旧 hybrid_tuner.py メイン機能)。"""

    lines = []
    lines.append("=" * 64)
    lines.append("engine.py  --report  (tuner summary)")
    lines.append("=" * 64)
    lines.append(f"  対局数         : {n_games}")
    lines.append(f"  formula版別    : {dict(sorted(version_counter.items()))}")
    lines.append(f"  total moves    : {len(records)}")

    # v2.44: Time_Aggression 有効値を表示 (stats から復元)
    _time_aggression_vals = set()
    for game_ver, cnt in version_counter.items():
        if game_ver >= "v2.44":
            _time_aggression_vals.add(game_ver)
    if _time_aggression_vals:
        lines.append("  ※ v2.44+ レコード含む — formula.time_aggression が stats に記録されています")
        lines.append(f"    現在の実効値: DL_Time_Ratio={_time_dyn.dl_time_ratio:.3f}  DL_Time_Max={_time_dyn.dl_time_max_ms:.0f}ms  SlowMover={_nnue_1_opts.get('SlowMover','?')}  aggr={_time_dyn.time_aggression}")
    else:
        lines.append(f"  現在の実効値 (v2.44): DL_Time_Ratio={_time_dyn.dl_time_ratio:.3f}  DL_Time_Max={_time_dyn.dl_time_max_ms:.0f}ms  SlowMover={_nnue_1_opts.get('SlowMover','?')}  aggr={_time_dyn.time_aggression}")

    dl_moves = [m for m in records if m.get("dl_used")]
    cache_hit = [m for m in dl_moves if m.get("prefetch_hit")]
    overrides = [m for m in records if m.get("council_override")]
    agree     = [m for m in dl_moves if m.get("dl_nnue_agree")]

    lines.append("")
    lines.append("── 基本統計 ──")
    lines.append(f"  dl_used        : {len(dl_moves)}手  ({_tuner_fmt_rate(_tuner_rate(len(dl_moves), len(records)))})")
    lines.append(f"  prefetch_hit   : {len(cache_hit)}手  ({_tuner_fmt_rate(_tuner_rate(len(cache_hit), len(dl_moves)))})")
    # [DLP-SRC] hit 出所内訳 — prefetch_hit は GPU ponder 収穫 (DL_Ponder) と
    # 投機 prefetch ([J] 含む) の合算なので、ここで分離して表示する。
    # ponder 比率が支配的なら prefetch_rate の改善議論は DLP 系で行うべき、の判別用。
    _hit_pon = [m for m in cache_hit if m.get("dl_cache_src") == "ponder"]
    _hit_pre = [m for m in cache_hit if m.get("dl_cache_src") in ("prefetch", "j")]
    _hit_unk = len(cache_hit) - len(_hit_pon) - len(_hit_pre)
    _src_line = (f"    └ 内訳: ponder={len(_hit_pon)}  prefetch={len(_hit_pre)}")
    if _hit_unk:
        _src_line += f"  旧record(出所不明)={_hit_unk}"
    lines.append(_src_line)
    lines.append(f"  council_override: {len(overrides)}手 ({_tuner_fmt_rate(_tuner_rate(len(overrides), len(records)))})")
    lines.append(f"  dl_nnue_agree  : {len(agree)}手  ({_tuner_fmt_rate(_tuner_rate(len(agree), len(dl_moves)))})")

    # lock-wait 分布
    lock_waits = [m.get("dl_lock_wait_ms") for m in dl_moves
                  if m.get("dl_lock_wait_ms") is not None and not m.get("prefetch_hit")]
    if lock_waits:
        sv = sorted(lock_waits)
        lines.append("")
        lines.append("── dl_lock_wait_ms 分布 (cache miss 時) ──")
        lines.append(f"  n={len(sv)}  min={sv[0]}  max={sv[-1]}")
        lines.append(
            f"  p50={_tuner_percentile(sv,50)}  p90={_tuner_percentile(sv,90)}"
            f"  p99={_tuner_percentile(sv,99)}"
        )
        high = sum(1 for v in sv if v > 2000)
        lines.append(f"  > 2000ms: {high}手 ({_tuner_fmt_rate(_tuner_rate(high, len(sv)))})")
        if high / len(sv) > 0.1:
            lines.append("  ⚠  lock_wait > 2s が 10%超。DL_Prefetch_Nodes の削減を検討。")

    # [Step 7A 2026-07-17] DL_2 統計節撤去 (dl_2_top_move schema 削除、DL_2 engine 全廃)。
    # RY3 推移は dl_top_move / nnue_bestmove 一致率と OPP-ID のみに縮退。
    try:
        _ry3_games = _tuner_load_games(_STATS_PATH)
        if _ry3_games:
            lines.append("")
            lines.append("── 一致率推移 (直近12局; DL_1==NNUE) ──")
            for _gi, _game in list(enumerate(_ry3_games, 1))[-12:]:
                _mvs = [m for m in _game.get("moves", [])
                        if m.get("dl_top_move") is not None
                        and m.get("nnue_bestmove") is not None]
                _agree = sum(1 for m in _mvs
                             if m.get("dl_top_move") == m.get("nnue_bestmove"))
                _all_mvs = _game.get("moves", [])
                # [OPP-ID v6.4] 相手系統観測の推移 — 不一致サンプルの命中内訳と
                # 現行 min_n/margin での分類。系統別の分離が見えてきたら
                # OppID_Margin を較正する判断材料 (観測先行)。
                _oid = [m.get("opponent_id_sample") for m in _all_mvs]
                _oid_nn = sum(1 for s in _oid if s == "nnue")
                _oid_dl = sum(1 for s in _oid if s == "dl")
                _oid_ms = sum(1 for s in _oid if s == "miss")
                _oid_n  = _oid_nn + _oid_dl + _oid_ms
                _oid_style = _opponent_style_classify_core(
                    _oid_nn, _oid_dl, _oid_n, _opponent_id_min_n, _opponent_id_margin)
                lines.append(
                    f"  game {_gi:>3}: agree {_agree}/{len(_mvs)} "
                    f"({_tuner_fmt_rate(_tuner_rate(_agree, len(_mvs)))})  "
                    f"opponent_id n={_oid_n} (nnue {_oid_nn}/dl {_oid_dl}/miss {_oid_ms}) "
                    f"→ {_oid_style or '保留'}"
                )
    except Exception as _ry3e:
        lines.append(f"  [RY3] 推移集計エラー (無視): {_ry3e}")

    # ── stale DL top パターン検出 (v2.51 回帰テスト) ──────────────────
    # prefetch_hit かつ dl_top_move が「直近 3 手の council_winner」と一致する手を
    try:
        _stale_hits   = []   # (game_idx, ply, dl_top, matched_winner) のリスト
        _stale_games  = _tuner_load_games(_STATS_PATH)
        for _gi, _game in enumerate(_stale_games, 1):
            _prev_winners = []   # ゲーム内の council_winner 履歴 (古い順)
            for _mv in _game.get("moves", []):
                _cw  = _mv.get("council_winner")
                _top = _mv.get("dl_top_move")
                _hit = _mv.get("prefetch_hit")
                if _hit and _top and _top in _prev_winners[-3:]:
                    _stale_hits.append((_gi, _mv.get("ply"), _top, _cw))
                if _cw:
                    _prev_winners.append(_cw)

        lines.append("")
        lines.append("── stale DL top 検出 (v2.51 回帰テスト) ──")
        lines.append("  [定義] prefetch_hit=True かつ dl_top_move == 直近 3 手の council_winner に一致")
        lines.append(f"  検出数: {len(_stale_hits)} 件 / {n_games} 局")
        if _stale_hits:
            lines.append("  ⚠  stale パターンを検出 — v2.51 修正が効いていない可能性があります。")
            lines.append("  ── 詳細 (最大 10 件) ──")
            for _gi, _ply, _top, _cw in _stale_hits[:10]:
                lines.append(f"    Game {_gi:3d}  ply={_ply}  dl_top={_top}  council_winner={_cw}")
            if len(_stale_hits) > 10:
                lines.append(f"    ... 他 {len(_stale_hits) - 10} 件 (省略)")
        else:
            lines.append("  ✓  stale パターンなし。")
    except Exception as _e:
        lines.append("")
        lines.append(f"  [stale 検出スキップ: {_e}]")

    # ── [S-7] 倍々窓テーブル (直近 10/20/40/80/… 局の W-D-L / 勝率 / R差) ──
    try:
        _dw_games = _tuner_load_games(_STATS_PATH)
        if _dw_games and len(_dw_games) >= 4:
            lines.append("")
            lines.append("── 倍々窓テーブル (最終局から遡り) ──")
            lines.append(f"  {'窓':>6s}  {'W':>4s}  {'D':>4s}  {'L':>4s}  {'勝率':>8s}  {'Elo差':>8s}")
            lines.append("  " + "-" * 44)
            _dw_window = 10
            while _dw_window <= len(_dw_games):
                _dw_tail = _dw_games[-_dw_window:]
                _dw_w = _dw_d = _dw_l = 0
                for _dg in _dw_tail:
                    _res = _dg.get("result") or _dg.get("meta", {}).get("result", "")
                    if _res in ("win", "sente_win", "gote_win", "+"):
                        _dw_w += 1
                    elif _res in ("lose", "sente_lose", "gote_lose", "-"):
                        _dw_l += 1
                    else:
                        _dw_d += 1
                _dw_n = _dw_w + _dw_d + _dw_l
                _dw_score = (_dw_w + _dw_d * 0.5) / _dw_n if _dw_n > 0 else 0.5
                _dw_elo = _sprt_elo_from_score(_dw_score) if 0 < _dw_score < 1 else 0.0
                lines.append(
                    f"  {_dw_window:>6d}  {_dw_w:>4d}  {_dw_d:>4d}  {_dw_l:>4d}  "
                    f"{_dw_score:>7.1%}  {_dw_elo:>+7.1f}")
                _dw_window *= 2
    except Exception as _dwe:
        lines.append(f"  [倍々窓スキップ: {_dwe}]")

    lines.append("")
    lines.append("=" * 64)
    _report_text = "\n".join(lines)
    print(_report_text)
    return _report_text
def _ab_compare_stats(path_a: str, path_b: str) -> str:
    """Reproducible A/B summary from two stats files."""
    rec_a, games_a, _ = _tuner_load_records(path_a)
    rec_b, games_b, _ = _tuner_load_records(path_b)
    a = _stats_rate(rec_a, games_a)
    b = _stats_rate(rec_b, games_b)
    lines = []
    lines.append("=" * 64)
    lines.append("A/B stats comparison")
    lines.append("=" * 64)
    lines.append(f"A: {path_a}")
    lines.append(f"B: {path_b}")
    lines.append("")
    for k in ["n", "override_rate", "prefetch_rate", "ponder_rate", "avg_eff_s", "avg_nnue_cp"]:
        va, vb = a[k], b[k]
        if isinstance(va, float):
            lines.append(f"{k:<16s} A={va:.4f}  B={vb:.4f}  Δ(B-A)={vb-va:+.4f}")
        else:
            lines.append(f"{k:<16s} A={va}  B={vb}  Δ(B-A)={vb-va:+d}")
    lines.append("=" * 64)
    return "\n".join(lines)


# ============================================================
# SPSA フレームワーク
# ============================================================


def _spsa_param_is_int(p: dict) -> bool:
    """resume 時に SpsaParam.is_int を決定する。"""
    if "is_int" in p:
        return bool(p["is_int"])
    for _k in ("min_val", "max_val", "step", "c"):
        _v = p.get(_k)
        if isinstance(_v, float) and not float(_v).is_integer():
            return False
    return True


@dataclasses.dataclass
class SpsaParam:
    """
    SPSA で調整するパラメータ 1 つの定義。

    Attributes
    ----------
    name       : config.txt のキー名 (例: "nnue_Trust_Base_Ply")
    value      : 現在値 (float; int パラメータも float で管理し書き込み時に丸める)
    min_val    : clamp の下限
    max_val    : clamp の上限
    step       : 摂動スケール s_i (fishtest の「c final」に相当)
                 やねうら王 記事の s ⊙ Δ の s_i 部分。
                 値が小さいほど細かく、大きいほど粗く摂動する。
    is_int     : True なら書き込み時に int に丸める
    """
    name:    str
    value:   float
    min_val: float
    max_val: float
    step:    float
    is_int:  bool = True

    def clamp(self, v: float) -> float:
        return _clamp(v, self.min_val, self.max_val)

    def config_value(self) -> "int | float":
        """config.txt に書き込む値 (int/float)。"""
        return int(round(self.value)) if self.is_int else round(self.value, 4)


@dataclasses.dataclass
class SpsaState:
    """
    SPSA セッション全体の状態。JSON にシリアライズして保存・再開できる。

    Attributes
    ----------
    params    : 調整対象パラメータリスト
    k         : 完了済みイテレーション数
    a0        : 学習率初期値 (fishtest: ak = a0 / (A + 1 + k) ** alpha)
    c0        : 摂動幅初期値 (fishtest: ck = c0 / (1 + k) ** gamma)
    A         : 安定化定数 (典型値: 全イテレーション数の 10%)
    alpha     : 学習率減衰指数 (fishtest 推奨 0.602)
    gamma     : 摂動幅減衰指数 (fishtest 推奨 0.101)
    total_iters: 予定イテレーション数 (収束判断・ck/ak のスケール調整用)
    """
    params:       list
    k:            int   = 0
    a0:           float = 2.0     # 0.02→2.0: 1イテレーション当たりの更新量を step の ~30% に修正
    c0:           float = 1.0
    A:            int   = 0       # 後で total_iters * 0.1 に設定
    alpha:        float = 0.602
    gamma:        float = 0.101
    total_iters:  int   = 1000
    # _deltas: 直前の spsa_perturbation() が生成した Rademacher ベクトル。
    # spsa_step() が参照するため、perturbation より先に step を呼ぶと IndexError になる。
    # JSON シリアライズ対象外 (from_dict では空リストで初期化)。
    _deltas: list = dataclasses.field(default_factory=list, repr=False, compare=False)
    # [POLYAK-RUPPERT 2026-06-22] 後半 25% iter の θ 平均を export 用に蓄積する。
    # 探索 θ 自身は不変 (sweep ノイズで揺れる) で、export config のみ averaged 値を出す
    # → 同じ局数で final config の Elo が安定する free-lunch (Spall ch.4 asymptotic optimal)。
    # 新ノブ不要 (window は total_iters の 25% を自動採用)。JSON 永続化済 = resume 整合。
    polyak_sum:   list = dataclasses.field(default_factory=list)
    polyak_count: int  = 0

    # fishtest 互換: ck, ak, rk を現在の k から計算
    def ck(self) -> float:
        return self.c0 / (1.0 + self.k) ** self.gamma

    def ak(self) -> float:
        return self.a0 / (self.A + 1.0 + self.k) ** self.alpha

    def rk(self) -> float:
        ck = self.ck()
        return self.ak() / (ck ** 2) if ck != 0.0 else 0.0

    @staticmethod
    def from_dict(d: dict) -> "SpsaState":
        params = [SpsaParam(
            name=p["name"], value=p["value"],
            min_val=p["min_val"], max_val=p["max_val"],
            step=p["step"],
            is_int=_spsa_param_is_int(p),
        ) for p in d.pop("params")]
        d.pop("_deltas", None)   # 古い JSON に含まれていても無視
        state  = SpsaState(params=params, **d)
        return state


# [SPSA-HW] 大会機向け縮約プロファイル — ハード/TC 依存キーの判定
#   判定本体 (_SPSA_HW_PATTERNS / _spsa_hw_key_core) は起動時の層別読み込み
#   (_load_config) も使うためファイル先頭 (early) へ移動した。
#   SPSA の所要対局数は次元にほぼ線形なので、縮約だけで所要が大幅に減る。


def _spsa_filter_profile_core(params, profile: str):
    """[SPSA-HW core] プロファイルでパラメータ列を縮約する (純粋)。

    profile="hw"   → ハード/TC 依存キーのみ (setup コマンド = デバイス依存調整)。
    profile="game" → ハード/TC 依存キーを除外 (spsa コマンド = ゲームロジック;
                     デバイス依存キーは setup が所有するため SPSA から分離)。
    それ以外       → 全キー (--profile full; レガシー互換)。
    Returns: (kept_list, dropped_names)
    """
    if profile == "hw":
        kept = [p for p in params if _spsa_hw_key_core(p.name)]
        dropped = [p.name for p in params if not _spsa_hw_key_core(p.name)]
        return kept, dropped
    if profile == "game":
        kept = [p for p in params if not _spsa_hw_key_core(p.name)]
        dropped = [p.name for p in params if _spsa_hw_key_core(p.name)]
        return kept, dropped
    return list(params), []


def _spsa_default_params() -> list:
    """ Build SPSA tunable parameter list from current config.

    [B1 ④' Phase 2] θ₀ の出所: 一部パラメータは module global でなく
    EngineConfig.from_cfg(_cfg) スナップショット (= clamp/正規化済みの
    実ロード値) から読む。★EngineConfig() デフォルトではない — defaults を
    使うと SPSA が現在値を失う退行 (ticket ★注意)。from_cfg は global 初期化と
    同一の clamp を再現する契約 (B/C/D 準備パターン) のため値はビット一致。
    global 直読みが残る _p はグループ B/C/D の保留シンボル (削除不可のもの)。

    Covers all §11 dynamic threshold families plus council weights
    and meta-parameters.  Each SpsaParam specifies:
      - name: config key
      - value: current loaded value (θ₀)
      - min_val / max_val: hard bounds
      - c: perturbation step size (≈ 5–10% of range)
      - a: gradient step size (≈ c/5, auto-scaled by spsa_step)

    Grouping:
      [A] GP handover（1 param; v4.40: handover_ply family 4 params から置換）
      [B] gap_min family          (4 params)
      [C] stab_threshold family   (4 params)
      [D] slow_mover family       (4 params)
      [E] DL budget               (3 params)
      [F] DL_2 margin             (3 params)
      [G1] depth_trust            (4 params)
      [G2] phase_trust (GP 軸)    (2 params; Phase 3 新設)
      [H] overlap_boost           (1 param)
      [I] phase weights           (6 params)
      [J] Time_Aggression x3      (3 meta-params; v4.33: DL/NNUE/Rescue 分解)
      [K] council weights         (2 params)
      [L] WR sigmoid discount     (4 params)
      [M] light council tuning    (3 params; v4.33 新規)
      [N] policy nodes / handover (5 params; v5.2: POLICY_NODES + DL_2_Node_Ratio 追加)
      [O] conviction override     (2 params; v4.33 新規)
      [P] GP phase params         (8 params; v4.35 新規)
      [Q] Disagreement boost      (7 params; 機能C 判断フェーズ 新規 + v4.39 GP スケール)
      [R] PV mate source flags    (2 params; v5.1 新規)

    Total: ~66 params
    """
    _scfg = EngineConfig.from_cfg(_cfg)   # θ₀ スナップショット
    params = []

    def _p(name, val, lo, hi, c=None, is_int=True):
        """Shorthand: create SpsaParam with auto c/a.

         is_int 引数を追加 (デフォルト True = 従来動作)。
        小数スケールのパラメータ (WR sigmoid 傾き等) は is_int=False を渡し、
        config_value() / perturbation で整数丸めされないようにする。
        """
        if c is None:
            c = max(0.01, (hi - lo) * 0.05)
        params.append(SpsaParam(
            name=name, value=float(val),
            min_val=float(lo), max_val=float(hi),
            step=c, is_int=is_int,
        ))

    # [A] GP handover（v4.40: nnue_Trust_* 4 params を 1 param に集約）
    _p("GP_Handover_Threshold", _scfg.game_phase_handover_threshold, 0.45, 0.95, c=0.04, is_int=False)
    # [可逆ハンドオーバー連動] handover_game_phase の eff_s 連動の傾き。0 で固定閾値 (旧動作)。
    # 0〜0.05 を探索: 長時間ほど nnue へ早く委ねる/短 byoyomi ほど DL を長く残す。
    # [S-4] レンジを両符号へ拡張。設計 (docstring / _get_handover_game_phase) は eff_s 増で
    #       handover 閾値を下げる「負」を要求するが、旧レンジ [0,0.05] は正のみで SPSA が符号を
    #       探索できなかった (符号バグの実体)。既定値は据え置き、符号は SPSA + SPRT で確定する。
    _p("GP_Handover_Per_Sec", _scfg.game_phase_handover_per_sec, -0.01, 0.01, c=0.002, is_int=False)
    # [CSA 時間切れ対策] 増分消費率。毎手 inc×ratio を eff_s floor にする。時間管理の核心。
    #  hi を 1.0 → 0.90 へ引き下げ ([EFFS-SPSA] と同型の盲目バイアス防壁)。
    #   導出: floor = inc×ratio − Move_Overhead だが、本番サーバには Move_Overhead
    #   (200ms) と同程度の通信・着手確定ラグが*別途*乗る (第5回電竜戦の実測知見:
    #   2 秒加算で実質使えるのは ~1.7s)。spend+ラグ ≤ inc を構造的に保証するには
    #   ratio ≤ 1 − Overhead/inc = 1 − 400/2000 = 0.80 (大会最小増分 2s 基準)。
    #   SPSA ローカル対局には本番のネットワークラグが無いため、TC ハーネスが
    #   フラグ落ちを負け計上するようになった今でも ratio→1.0 方向の損失は
    #   ローカルで不可視 (上げ得に見える)。よって探索域から構造的に排除する。
    #   ratio=1.0 は純増ゼロ (貯金が永遠に増えない) で 0分+2秒ではヒッカップ
    #   1 回が即負けになる点でも上限として不適。
    _inc_spend_ratio_clamped = min(0.80, _inc_spend_ratio)
    _p("Inc_Spend_Ratio", _inc_spend_ratio_clamped, 0.7, 0.80, c=0.02, is_int=False)
    # [短時間Fischer対策] inc>0 時の rem_moves 上限。小さいほど 1 手に厚く張る
    # (貯金を早く消費)、大きいほど取り置きが増えて保守的。短時間Fischer専用 SPSA
    # run で振る。is_int=True (手数は整数)。0 にはしない (機能無効化は別途設定で)。
    _p("Fischer_Horizon_Moves", _fischer_horizon_moves, 20, 36, c=1.0, is_int=True)
    # [可逆ハンドオーバー] 解除ヒステリシス幅。振動と感度のトレードオフ。
    _p("Handover_Reverse_Hysteresis", _scfg.handover_reverse_hysteresis, 0.0, 0.15, c=0.01, is_int=False)
    # [Step 4C 2026-07-17] Endgame_DL_Veto_* / Handover_Reverse_Hysteresis_Shrink
    # SPSA params 撤去 (endgame lane 全廃)。

    # [B] gap_min
    # 旧: lo=0, hi=500 / lo=0, hi=50 / lo=0, hi=200 / lo=100, hi=2000
    _p("DL_Score_Gap_Min_Base",    _dl_gap_min_base,    10,  40)
    _p("DL_Score_Gap_Min_Per_Sec", _dl_gap_min_per_sec, 0.2, 1.0, is_int=False)
    _p("DL_Score_Gap_Min_Min",     _dl_gap_min_min,     10,  40)
    _p("DL_Score_Gap_Min_Max",     _dl_gap_min_max,     25,  60)
    # [GP] gap_min の GP 依存係数。単一係数で、負なら終盤ほど gap を厳しく・
    # 正なら緩くする (探索域を負〜正に開ける)。0 = 現状 (GP 非依存)。
    _p("DL_Score_Gap_Min_GP_Coef", _dl_gap_min_game_phase_coef, -30.0, 30.0, c=2.0, is_int=False)

    # [C] stab_threshold
    # 旧: lo=0, hi=500 / lo=0, hi=50 / lo=0, hi=200 / lo=100, hi=2000
    _p("DL_Stability_Threshold_Base",    _dl_stab_base,    90,  220)
    _p("DL_Stability_Threshold_Per_Sec", _dl_stab_per_sec, 1.5, 5.0, is_int=False)
    _p("DL_Stability_Threshold_Min",     _dl_stab_min,     50,  130)
    _p("DL_Stability_Threshold_Max",     _dl_stab_max,     160, 360)

    # [D] slow_mover
    # 旧: lo=50, hi=300 / lo=0, hi=30 / lo=50, hi=200 / lo=100, hi=500
    _p("SlowMover_Base",    _scfg.slow_mover_base,    60,  120)
    _p("SlowMover_Per_Sec", _scfg.slow_mover_per_sec, 4.0, 10.0, is_int=False)
    _p("SlowMover_Min",     _scfg.slow_mover_min,     70,  140)
    _p("SlowMover_Max",     _scfg.slow_mover_max,     140, 270)

    # [E] DL budget
    # 旧: lo=0.02, hi=0.40 / lo=100, hi=5000 / lo=5000, hi=60000
    #   config.txt が 0 (未設定) の場合、そのまま使うと最初の数イテレーションが clamp され続けノイズになる。
    _dl_time_ratio_clamped = _clamp(_time_dyn.dl_time_ratio, 0.15, 0.38)
    _p(_K_DL_TIME_RATIO,  _dl_time_ratio_clamped,  0.15, 0.38, c=0.02, is_int=False)
    _p("DL_Time_Min_ms", _dl_time_min_ms, 900,  2500)
    _p("DL_Time_Max_ms", _time_dyn.dl_time_max_ms, 22000, 50000)

    # [PHASE2 Step 3] [F]/[F+] DL_2 margin / 暴走対策 SPSA params removed (council engine 撤去)。

    # [G1] depth_trust（探索品質軸）— 浅い prefetch 票の検出能力を維持
    # 旧: lo=0.0, hi=2.0 / lo=0.0, hi=0.5 / lo=0.0, hi=1.0 / lo=0.5, hi=3.0
    _p("DL1_Council_Depth_Trust_Base",      _scfg.dl1_depth_trust_base,      0.25, 0.60, c=0.05, is_int=False)
    _p("DL1_Council_Depth_Trust_Per_Depth", _scfg.dl1_depth_trust_per_depth, 0.02, 0.08, c=0.01, is_int=False)
    _p("DL1_Council_Depth_Trust_Min",       _scfg.dl1_depth_trust_min,       0.40, 0.85, c=0.04, is_int=False)
    _p("DL1_Council_Depth_Trust_Max",       _scfg.dl1_depth_trust_max,       0.65, 1.40, c=0.06, is_int=False)

    # [G2] phase_trust（進行度軸） — GP が高いほど DL_1 票を割り引く
    # depth_trust と直交する独立乗数。デフォルト 1.0/1.0 = 無効。
    # SPSA 観測後に Min を 0.6〜0.8 程度まで下げて効かせること。
    _p("DL1_GP_Trust_Min", _scfg.dl1_game_phase_trust_min, 0.50, 1.00, c=0.04, is_int=False)
    _p("DL1_GP_Trust_Max", _scfg.dl1_game_phase_trust_max, 0.80, 1.20, c=0.03, is_int=False)
    # [S-6] score_gap 正規化スケール (phase-trust の gap 軸; gp 共線解消)。
    _p("GAP_NORM_CP", float(_scfg.gap_norm_cp), 200, 1000, c=40, is_int=True)

    # [H] overlap_boost
    # 旧: lo=1.0, hi=3.0
    _p("DL1_Council_PV_Overlap_Max_Boost", _scfg.dl1_pv_overlap_max_boost, 1.0, 1.5, c=0.05, is_int=False)

    # [DL-BONUS-PURGE 2026-07-17] 残り 3 件の SPSA 登録も撤去し [DL-BONUS] 群は消滅。
    # Step 6B が Council_WR_Discount_Min_Conviction / GP_Surge_DL_Trust_Restore を
    # 「vote-line 消費者ゼロ」で撤去した際、同型の 3 件が残っていた。消費者ゼロの
    # ノブを SPSA に登録すると、効果ゼロの摂動に自己対局を費やし続ける。

    # [NARROW-SEARCH] (TopN=0 はゲートトグルなので SPSA 非登録。閾値のみ)
    _p("Council_Narrow_Search_Min_Eff_S", _scfg.council_narrow_search_min_eff_s, 1.0, 10.0, c=0.5, is_int=False)
    _p("Council_Narrow_Search_Min_Decisiveness", _scfg.council_narrow_search_min_decisiveness, 0.3, 0.9, c=0.05, is_int=False)

    # [I] phase weights — Phase 2 で GP 入力に置換 (Decay_End_Ply 廃止)
    # Weight_Early/Late は GP スケール (0→1) に合わせて再 SPSA。
    # [MAXMIN v6.5] 接戦票 max-min タイブレークの僅差帯幅。lo=0.0 を許す
    # (SPSA が 0 へ寄せれば機能の実質無効化まで裁定できる)。
    _p("MaxMin_Tie_Margin", _scfg.maxmin_tie_margin, 0.0, 0.25, c=0.02, is_int=False)
    # [DL1-WEIGHT-PURGE 2026-07-17] SPSA 登録撤去 — 消費者ゼロのノブを摂動しても
    # 自己対局を捨てるだけ (dl2_weight_* を撤去した Step 6B の取りこぼし)。
    # [Step 6B 2026-07-17] DL2_Council_Weight_Early/Late SPSA 撤去。

    # [J] Time_Aggression — base 一本化 (TA-base SPSA)
    #   v4.33 では DL/NNUE/Rescue の 3 子ノブを独立 SPSA していたが、いずれも
    #   _lerp の補間係数 t にしか効かず t=1 で頭打ち (DL_Ratio hi=0.25 の壁) のため、
    #   上げ方向に relay_cap が動かなかった。base を出力レンジのスケーラ役に変えた
    #   (_compute_go_time_dynamics の gain=base/ANCHOR) ことで base が実効ノブになった
    #   ため、ここでは base 1 本を SPSA し、子ノブ3つは inherit (=base 追従) に戻して
    #   SPSA から外す。base と子/lerp 端点を同時に振ると相関が大きく相殺解に落ちる
    #   ため、時間投入を支配するノブは base に一本化する (二重調整回避)。
    #
    #   レンジ: Time_Aggression は全持ち時間で共通の基準値なので、特定 TC に過適合
    #     しないよう広めに取る。base=ANCHOR(0.85)=現行固定値を中心域に含める。
    #     下限 0.55: 超短時間でも DL を捨てない床 (gain 下限 0.55 と整合)。
    #     上限 1.20: gain 上限 1.41 相当。_TA_CEIL(1.25)・gain クランプ(1.60) の内側で
    #     下流が時間切れに至らない安全域。c=0.05 は子ノブと同等の摂動幅。
    _p(_K_TIME_AGGRESSION, _time_aggression_base, 0.55, 1.20, c=0.05, is_int=False)
    # 子ノブ (Time_Aggression_DL/_NNUE/_Rescue) は inherit 既定 (-1) に戻し SPSA 非対象。
    # 旧 SPSA 登録 (_p 0.55〜1.15 x3) は base 一本化に伴い撤去 (二重調整回避)。

    # [K] council weights
    # [CORR-DAMP] 相関票減衰強度。既定 0.0=no-op を SPSA が 0〜0.5 で探る (2008 合議論文)。
    _p("Council_Corr_Dampen",       _scfg.council_corr_dampen,        0.0,  0.5,  c=0.04, is_int=False)
    # [DL3代弁] SPSA 調整候補。Mode/Scope は離散のため SPSA 外 (手動切替)。
    _p("DL3_Proxy_Fuse_Alpha",      _scfg.dl3_proxy_fuse_alpha,       0.0,  1.0,  c=0.08, is_int=False)
    _p("DL3_Proxy_Weight_Min",      _scfg.dl3_proxy_weight_min,       0.3,  1.0,  c=0.05, is_int=False)
    _p("DL3_Proxy_Weight_Max",      _scfg.dl3_proxy_weight_max,       1.0,  2.2,  c=0.08, is_int=False)
    _p("DL3_Proxy_NNUE_Base_Weight", _scfg.dl3_proxy_nnue_base_w,     0.6,  1.6,  c=0.06, is_int=False)
    _p("Council_Score_Discount_Threshold", _scfg.council_score_discount_threshold, 120, 300)

    # [L] cp→勝率変換ディスカウント
    # [Step 6B 2026-07-17] Council_WR_* SPSA 登録全撤去 (EngineConfig field 全廃)。
    # 消費 (_win_rate_params_for_phase → LIVE-BOARD / arbiter shim 経路) は
    # _sv_wr_phase_cfg() が _cfg 直参照で継続。SPSA での再較正は現バージョンで停止し、
    # WR-COMPAT teacher / gp_cal 書き出しの静的値でメンテナンスする方針。

    # [M]  Light council チューニング
    # [Step 4C 2026-07-17] Endgame_Min_Eff_S SPSA param 撤去 (endgame lane 全廃)。
    # [Step 4D 2026-07-17] Light_Council_DL3_Weight SPSA param 撤去 (DL_3 engine 全廃)。
    _p("DL_Time_Ratio_Eff_S_Coef",   _dl_time_ratio_eff_s_coef, -0.02, 0.02, c=0.002, is_int=False)

    # [N]  POLICY_NODES 動的スケール & Handover 合意閾値
    #   POLICY_NODES      : DL_1 go nodes のベース値 (setoption で可変)。
    #   policy_nodes_per_eff_s は 1 秒あたり何ノード追加するかを制御する。
    #   handover_agree/instab は DL→NNUE 引き継ぎの閾値。
    # [PHASE2 Step 3] DL_2_Node_Ratio SPSA param removed (council engine 撤去)。
    # 旧: lo=100, hi=2000 / lo=0.5, hi=1.0 / lo=1.0, hi=3.0
    _p(_K_POLICY_NODES,             float(_params[_K_POLICY_NODES]), 500, 6000, c=200)
    _p("POLICY_NODES_Per_Eff_S",      _scfg.policy_nodes_per_eff_s,    300,  750,  c=30)
    # [N+ ponder/prefetch go nodes] 相手手番の先読み (ponder 代替 prefetch) の
    # 探索量。go node は探索の強さを直接決めるため SPSA で詰める (大会方針)。
    #   DL_Prefetch_Nodes     : 速報 prefetch の go nodes。小さいほど ponder miss
    #     後の stop 応答が速いが先読みが浅い。GPU 潤沢環境では引き上げ余地大。
    #   DL_Prefetch_IDP_Nodes : ponderhit 時 council に渡す高品質 policy の再探索
    #     ノード。0=POLICY_NODES 同値だったが、SPSA では明示下限を持たせて振る。
    _p("DL_Prefetch_Nodes",        float(_dl_prefetch_nodes),   200, 4000, c=150)
    _p("DL_Prefetch_IDP_Nodes",    float(_dl_prefetch_idp_nodes if _dl_prefetch_idp_nodes > 0
                                         else _params[_K_POLICY_NODES]),
                                                                500, 8000, c=250)
    # [N+ council policy width] council が DL_1 から採用する候補手数 (policy の幅)。
    # 広いほど DL の手を council 投票に多く乗せる = council の多様性。狭いほど
    # DL top に集中。council policy も SPSA 対象にする (大会方針)。
    _p(_K_POLICY_MOVES,             float(_params[_K_POLICY_MOVES]), 3, 20, c=1)

    # [O]  Conviction override チューニング
    #   確信度スコア差による DL 強制採用の閾値を SPSA で最適化する。
    #   Council_Override_Min_Diff_cp は DL vs NNUE の最低スコア差 (cp)。
    #   DL_Conviction_Score_Gap_cp は DL 1 位と 2 位の最低差 (cp)。
    # 旧: lo=0, hi=500 / lo=100, hi=2000
    _p("Council_Override_Min_Diff_cp",     _cfloat(_cfg, "Council_Override_Min_Diff_cp", 50),
                                                                    45,  150, c=10)
    _p("DL_Conviction_Score_Gap_cp",       _cfloat(_cfg, "DL_Conviction_Score_Gap_cp", 538),
                                                                    280, 750, c=40)

    # [P]  GP 進行度パラメータ（仕様書 §7）
    #   GP 算出式の各係数と感度パラメータを SPSA で最適化する。
    #   GP_W_*    : 各シグナルの重み（is_int=False の連続値）
    #   GP_*_Ref  : 各シグナルの正規化基準（典型的フルゲーム相当値）
    #   GP_Scale  : 飽和曲線の全体感度（小=鋭敏、大=緩慢）
    #   DL_Stability_GP_Tighten: game_phase が高いほど stability 閾値を厳しくする量 (cp)
    _p("GP_W_Hand",    _game_phase_w_hand,    0.0,  2.0,  c=0.10, is_int=False)
    _p("GP_W_Promo",   _game_phase_w_promo,   0.0,  2.5,  c=0.12, is_int=False)
    _p("GP_W_Camp",     _game_phase_w_camp,     0.0,  1.5,  c=0.08, is_int=False)
    _p("GP_W_King",    _game_phase_w_king,    0.0,  3.0,  c=0.15, is_int=False)   # [GP-玉つり上げ]
    _p("GP_Hand_Ref",  _game_phase_hand_ref,  4.0,  28.0, c=1.0,  is_int=False)
    _p("GP_Promo_Ref", _game_phase_promo_ref, 3.0,  20.0, c=1.0,  is_int=False)
    _p("GP_Camp_Ref",   _game_phase_camp_ref,   3.0, 44.0, c=1.5,  is_int=False)
    _p("GP_King_Ref",  _game_phase_king_ref,  0.3, 12.0, c=0.5,  is_int=False)   # [GP-玉つり上げ] 玉前進(現在状態)の深さ正規化基準
    # [GP-v3] 駒種価値 (FU はスケールアンカーのため非登録)
    _p("GP_Hand_Val_KY", _gp_hand_vals[1], 0.5, 20.0, c=0.3, is_int=False)
    _p("GP_Hand_Val_KE", _gp_hand_vals[2], 0.5, 20.0, c=0.3, is_int=False)
    _p("GP_Hand_Val_GI", _gp_hand_vals[3], 0.5, 20.0, c=0.3, is_int=False)
    _p("GP_Hand_Val_KI", _gp_hand_vals[4], 0.5, 20.0, c=0.3, is_int=False)
    _p("GP_Hand_Val_KA", _gp_hand_vals[5], 0.5, 20.0, c=0.3, is_int=False)
    _p("GP_Hand_Val_HI", _gp_hand_vals[6], 0.5, 20.0, c=0.3, is_int=False)
    _p("GP_Camp_Val_FU", _gp_camp_vals[0], 0.0, 20.0, c=0.3, is_int=False)
    _p("GP_Camp_Val_KY", _gp_camp_vals[1], 0.0, 20.0, c=0.3, is_int=False)
    _p("GP_Camp_Val_KE", _gp_camp_vals[2], 0.0, 20.0, c=0.3, is_int=False)
    _p("GP_Camp_Val_GI", _gp_camp_vals[3], 0.0, 20.0, c=0.3, is_int=False)
    _p("GP_Camp_Val_KI", _gp_camp_vals[4], 0.0, 20.0, c=0.3, is_int=False)
    _p("GP_Camp_Val_KA", _gp_camp_vals[5], 0.0, 20.0, c=0.3, is_int=False)
    _p("GP_Camp_Val_HI", _gp_camp_vals[6], 0.0, 20.0, c=0.3, is_int=False)
    _p("GP_Camp_Val_TO", _gp_camp_vals[7], 0.0, 20.0, c=0.3, is_int=False)
    _p("GP_Camp_Val_NY", _gp_camp_vals[8], 0.0, 20.0, c=0.3, is_int=False)
    _p("GP_Camp_Val_NK", _gp_camp_vals[9], 0.0, 20.0, c=0.3, is_int=False)
    _p("GP_Camp_Val_NG", _gp_camp_vals[10], 0.0, 20.0, c=0.3, is_int=False)
    _p("GP_Camp_Val_UM", _gp_camp_vals[11], 0.0, 20.0, c=0.3, is_int=False)
    _p("GP_Camp_Val_RY", _gp_camp_vals[12], 0.0, 20.0, c=0.3, is_int=False)
    _p(_K_GP_NYUGYOKU_KING_ONSET, _game_phase_nyugyoku_king_onset, 0.1, 9.0,  c=0.4, is_int=False)  # [GP-入玉域] 加点開始深さ
    _p("GP_Nyugyoku_King_Full",  _game_phase_nyugyoku_king_full,  0.3, 12.0, c=0.4, is_int=False)  # [GP-入玉域] 加点満額深さ
    _p("GP_Scale",     _game_phase_scale,     0.7,  2.5,  c=0.10, is_int=False)
    _p("GP_W_Exposure", _game_phase_w_exposure, 0.0, 1.5, c=0.08, is_int=False)
    _p("GP_Exposure_Ref", _game_phase_exposure_ref, 3.0, 16.0, c=1.0, is_int=False)
    # [GP-DEV/CONTACT 2026-07-17] §9.5-a/b。hi は実測レンジから: DEV 0..40 (駒組み完了
    # ≈15)、CONTACT は仕掛け前 0 → 乱戦で十数。既定 0.0 なので SPSA 未実施なら no-op。
    _p("GP_W_Dev",      _game_phase_w_dev,      0.0, 1.5,  c=0.08, is_int=False)
    _p("GP_Dev_Ref",    _game_phase_dev_ref,    4.0, 40.0, c=2.0,  is_int=False)
    _p("GP_W_Contact",  _game_phase_w_contact,  0.0, 1.5,  c=0.08, is_int=False)
    _p("GP_Contact_Ref", _game_phase_contact_ref, 1.0, 20.0, c=1.0, is_int=False)
    _p("GP_Child_Pull", _game_phase_child_pull, 0.0, 0.5, c=0.03, is_int=False)
    _p("DL_Stability_GP_Tighten", _cfloat(_cfg, "DL_Stability_GP_Tighten", 9), -80.0, 80.0, c=4.0, is_int=False)

    # [Q] [機能C 判断フェーズ] Disagreement 時間延長 & Score Stability 延長
    #   常時 ON (Disagree_Boost_Enable トグル撤去済)。
    #   初期値 1.0 / 9999 は「無効」状態。観測データ蓄積後に SPSA で最適化する。
    #   Disagree_Eff_S_Boost_Score1/2  : disagreement_score=1/2 かつ score_gap >= 閾値
    #     のときの eff_s 倍率。1.0 = 延長なし。1.2〜1.5 程度を探索範囲とする。
    #   Disagree_Score_Gap_Threshold_Cp: ブーストを発動する最低 score_gap (cp)。
    #     小さいほど頻繁にブーストが発火する。100〜250cp 程度が目安。
    #   Score_Stability_Swing_Threshold_Cp: 前手比スコア変動量の発動閾値 (cp)。
    #     観測値の 75〜90 パーセンタイル相当に設定することを推奨。
    #   Score_Stability_Eff_S_Boost: Stability 延長の倍率。1.0 = 無効。
    _p("Disagree_Eff_S_Boost_Score1",
       _scfg.disagree_eff_s_boost_score1,    1.0, 1.8, c=0.05, is_int=False)
    _p("Disagree_Eff_S_Boost_Score2",
       _scfg.disagree_eff_s_boost_score2,    1.0, 2.0, c=0.07, is_int=False)
    _p("Disagree_Score_Gap_Threshold_Cp",
       float(_scfg.disagree_score_gap_threshold_cp), 50.0, 400.0, c=20.0)
    _p("Score_Stability_Swing_Threshold_Cp",
       float(_scfg.score_stability_swing_threshold_cp), 50.0, 600.0, c=30.0)
    _p("Score_Stability_Eff_S_Boost",
       _scfg.score_stability_eff_s_boost,    1.0, 1.8, c=0.05, is_int=False)
    #  GP 軸スケール: 0.0=序盤完全無効〜1.0=序盤フルブースト
    _p("Score_Stability_GP_Scale_Min",
       _scfg.score_stability_game_phase_scale_min,   0.0, 0.8, c=0.05, is_int=False)
