    # [SF-TIME] 動的時間サブノブ (Stockfish 由来)。
    _p("Time_Fall_Gain",            float(_scfg.time_aggression_fall_gain),            0.0, 0.5, c=0.03, is_int=False)
    _p("Time_Fall_Floor",           float(_scfg.time_aggression_fall_floor),           0.4, 1.0, c=0.03, is_int=False)
